{
  "name": "contract-guard",
  "version": "1.0.0",
  "description": "API contract registry: version specs, detect breaking changes, track affected consumers, block dangerous publishes.",
  "type": "module",
  "main": "src/index.js",
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "start": "node src/index.js",
    "test": "node --test test/",
    "test:engine": "node --test test/engine.test.js"
  },
  "dependencies": {
    "express": "^5.1.0",
    "js-yaml": "^4.1.0",
    "pg": "^8.13.0"
  }
}

/**
 * Typed error used across the analysis pipeline.
 * stage: 'parse' | 'validate' | 'resolve' | 'flatten' | 'diff' | 'impact' | 'persist' | 'notify'
 * Any thrown GuardError means Contract Guard could not do its job -> fail safe (publish refused).
 */
export class GuardError extends Error {
  constructor(stage, message, detail) {
    super(message);
    this.name = 'GuardError';
    this.stage = stage;
    this.detail = detail;
  }
}

/** Wrap an unexpected error into a GuardError so every failure carries its pipeline stage. */
export function asGuardError(stage, err) {
  if (err instanceof GuardError) return err;
  const e = new GuardError(stage, err?.message || String(err));
  e.stack = err?.stack;
  return e;
}

import yaml from 'js-yaml';
import { GuardError } from './errors.js';

/**
 * Parse a YAML (or JSON, which is valid YAML) document into a plain object.
 * Fails loudly with stage 'parse' - a spec we cannot read is a failed publish, never a silent pass.
 */
export function parseYaml(text) {
  if (typeof text !== 'string' || !text.trim()) {
    throw new GuardError('parse', 'Specification body is empty.');
  }
  let doc;
  try {
    doc = yaml.load(text, { schema: yaml.JSON_SCHEMA });
  } catch (err) {
    throw new GuardError('parse', `YAML could not be parsed: ${err.message.split('\n')[0]}`, {
      reason: err.message,
    });
  }
  if (doc === null || doc === undefined) {
    throw new GuardError('parse', 'Specification parsed to an empty document.');
  }
  if (typeof doc !== 'object' || Array.isArray(doc)) {
    throw new GuardError('parse', 'Specification must be a YAML mapping, not a scalar or list.');
  }
  return doc;
}

import { GuardError } from './errors.js';

const HTTP_METHODS = new Set(['get', 'put', 'post', 'delete', 'options', 'head', 'patch', 'trace']);

/**
 * Structural validation of an OpenAPI document. We only need what the comparison relies on:
 * a title/version and path -> method -> operation tree. Anything the guard cannot understand
 * must fail here rather than produce a silent, misleading diff.
 */
export function validateSpec(doc) {
  const problems = [];
  if (!doc.openapi || typeof doc.openapi !== 'string') {
    problems.push('Missing "openapi" version string (only OpenAPI documents are analysed).');
  }
  if (!doc.info || typeof doc.info !== 'object') {
    problems.push('Missing "info" object.');
  } else {
    if (!doc.info.version || typeof doc.info.version !== 'string') {
      problems.push('Missing "info.version" string.');
    }
    if (!doc.info.title || typeof doc.info.title !== 'string') {
      problems.push('Missing "info.title" string.');
    }
  }
  if (!doc.paths || typeof doc.paths !== 'object' || Array.isArray(doc.paths)) {
    problems.push('Missing "paths" object.');
  } else {
    for (const [path, pathItem] of Object.entries(doc.paths)) {
      if (!path.startsWith('/')) problems.push(`Path "${path}" should start with "/".`);
      if (!pathItem || typeof pathItem !== 'object' || Array.isArray(pathItem)) {
        problems.push(`Path "${path}" is not an object.`);
        continue;
      }
      const ops = Object.keys(pathItem).filter((k) => HTTP_METHODS.has(k.toLowerCase()));
      if (ops.length === 0) problems.push(`Path "${path}" defines no operations.`);
    }
  }
  if (problems.length) {
    throw new GuardError('validate', `Specification is not a usable OpenAPI document: ${problems[0]}`, {
      problems,
    });
  }
  return doc;
}

/**
 * Resolve every internal `$ref` (`#/components/schemas/...` style) in a validated document.
 * Returns a deep-ish copy with refs replaced by the referenced node, plus the list of
 * components used, so the flattener compares what goes over the wire, not file organisation.
 *
 * Broken or external refs throw (stage 'resolve') - fail safe.
 * Reference cycles are cut at maxDepth so the resolver always terminates.
 */
export function resolveRefs(doc, { maxDepth = 32 } = {}) {
  const errors = [];

  function deref(node, depth, seen) {
    if (node === null || typeof node !== 'object') return node;
    if (Array.isArray(node)) return node.map((item) => deref(item, depth, seen));

    if (typeof node.$ref === 'string') {
      const target = lookupRef(doc, node.$ref, errors);
      if (target === undefined) {
        return node; // error recorded; validation of results happens after traversal
      }
      if (depth >= maxDepth || seen.has(node.$ref)) {
        // Cycle: keep a marker so the flattener can stop instead of spinning.
        return { ...omitRefKeys(node), 'x-guard-cycle': node.$ref };
      }
      const nextSeen = new Set(seen);
      nextSeen.add(node.$ref);
      const resolved = deref(omitRefKeys(target), depth + 1, nextSeen);
      // Keep siblings the spec defines next to $ref (rare but legal in OpenAPI 3.0).
      return { ...resolved, ...deref(omitRefKeys(node), depth + 1, nextSeen) };
    }

    const out = {};
    for (const [key, value] of Object.entries(node)) {
      out[key] = deref(value, depth, seen);
    }
    return out;
  }

  const resolved = deref(doc, 0, new Set());
  if (errors.length) {
    throw new GuardError('resolve', `Unresolvable $ref in specification: ${errors[0]}`, {
      brokenRefs: errors,
    });
  }
  return resolved;
}

function omitRefKeys(node) {
  if (!node || typeof node !== 'object' || Array.isArray(node)) return node;
  const { $ref, summary, description, ...rest } = node;
  const out = { ...rest };
  if (description) out.description = description;
  return out;
}

function lookupRef(doc, ref, errors) {
  if (!ref.startsWith('#/')) {
    errors.push(`${ref} (external references are not supported)`);
    return undefined;
  }
  let current = doc;
  for (const rawSegment of ref.slice(2).split('/')) {
    const segment = decodeURIComponent(rawSegment.replace(/~1/g, '/').replace(/~0/g, '~'));
    if (current === null || typeof current !== 'object' || !(segment in current)) {
      errors.push(`${ref} (target does not exist)`);
      return undefined;
    }
    current = current[segment];
  }
  return current;
}

import { GuardError } from './errors.js';

const HTTP_METHODS = new Set(['get', 'put', 'post', 'delete', 'options', 'head', 'patch', 'trace']);
const MAX_DEPTH = 24;

/**
 * Turn a resolved OpenAPI document into the wire model Contract Guard reasons about:
 *
 *   { title, version, endpoints: [ { key, method, path, internal, deprecated,
 *       pathParams, queryParams, headerParams, cookieParams,
 *       request: { required, fields: FieldNode[] },
 *       responses: { '200': { fields: FieldNode[] } } } ] }
 *
 * FieldNode = { path: 'premium.breakdown[].amount', type, required, enum, format,
 *               deprecated, sunset, union }
 *
 * Every `$ref` has already been resolved, so two specs that describe the same contract
 * flatten to the same model even when organised completely differently.
 */
export function flattenSpec(doc) {
  if (!doc || typeof doc !== 'object' || !doc.paths) {
    throw new GuardError('flatten', 'Document passed to flattener is missing "paths".');
  }

  const endpoints = [];
  for (const [path, pathItem] of Object.entries(doc.paths)) {
    if (!pathItem || typeof pathItem !== 'object') continue;
    const pathInternal = pathItem['x-internal'] === true;
    for (const methodKey of Object.keys(pathItem)) {
      const method = methodKey.toLowerCase();
      if (!HTTP_METHODS.has(method)) continue;
      const op = pathItem[methodKey];
      if (!op || typeof op !== 'object') continue;
      const internal = pathInternal || op['x-internal'] === true;

      const allParams = mergeParams(pathItem.parameters, op.parameters);
      const params = { path: [], query: [], header: [], cookie: [] };
      for (const p of allParams) {
        const location = p.in || 'query';
        if (!params[location]) continue; // unknown location: ignored, noted in analysis
        params[location].push({
          name: p.name,
          required: location === 'path' ? p.required !== false : p.required === true,
          node: flattenSchema(p.schema, p.name, {}, location === 'path')[0] || {
            path: p.name,
            type: 'unknown',
            required: true,
          },
        });
      }

      const request = flattenRequestBody(op.requestBody);
      const responses = flattenResponses(op.responses);

      endpoints.push({
        key: `${method.toUpperCase()} ${normalizePath(path)}`,
        method: method.toUpperCase(),
        path,
        pathParams: params.path,
        queryParams: params.query,
        headerParams: params.header,
        cookieParams: params.cookie,
        operationId: op.operationId || null,
        summary: op.summary || null,
        deprecated: op.deprecated === true,
        internal,
        request,
        responses,
      });
    }
  }

  endpoints.sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
  return {
    title: doc.info?.title || '(untitled)',
    version: doc.info?.version || '(no version)',
    description: doc.info?.description || '',
    openapi: doc.openapi || '',
    endpoints,
  };
}

export function normalizePath(path) {
  return String(path).replace(/\{[^/}]*\}/g, '{}');
}

function mergeParams(pathLevel = [], opLevel = []) {
  const out = [];
  const seen = new Set();
  for (const p of [...(opLevel || []), ...(pathLevel || [])]) {
    if (!p || typeof p !== 'object' || !p.name) continue;
    const id = `${p.in}:${p.name}`;
    if (seen.has(id)) continue;
    seen.add(id);
    out.push(p);
  }
  return out;
}

function flattenRequestBody(body) {
  if (!body || typeof body !== 'object') return { present: false, required: false, fields: [] };
  const schema = firstContentSchema(body.content);
  return {
    present: true,
    required: body.required === true,
    fields: schema ? flattenSchema(schema, '', {}, false) : [],
    schemaless: !schema,
  };
}

function flattenResponses(responses) {
  const out = {};
  if (!responses || typeof responses !== 'object') return out;
  for (const [status, resp] of Object.entries(responses)) {
    if (!resp || typeof resp !== 'object' || status.startsWith('x-')) continue;
    const schema = firstContentSchema(resp.content);
    out[status] = {
      description: resp.description || '',
      fields: schema ? flattenSchema(schema, '', {}, false) : [],
      schemaless: !schema,
    };
  }
  return out;
}

/** First application/json schema (fall back to the first content entry with a schema). */
function firstContentSchema(content) {
  if (!content || typeof content !== 'object') return null;
  const json = content['application/json'];
  if (json?.schema) return json.schema;
  for (const media of Object.values(content)) {
    if (media && typeof media === 'object' && media.schema) return media.schema;
  }
  return null;
}

/** Join a parent wire path with a child segment ('' + name, or parent + '.' + name / '[]'). */
export function joinPath(parent, segment) {
  if (!parent) return segment;
  if (segment === '[]') return `${parent}[]`;
  return `${parent}.${segment}`;
}

/**
 * Flatten one schema node into the `out` list. Returns `out` for convenience.
 * `assumeRequired` marks path parameters (required by definition).
 */
export function flattenSchema(schema, basePath, out = {}, assumeRequired = false) {
  if (out.__list === undefined) Object.assign(out, { __list: [] });
  const list = out.__list;
  walk(schema, basePath, list, assumeRequired, 0);
  return list;
}

function walk(schema, basePath, list, assumeRequired, depth) {
  if (depth > MAX_DEPTH) {
    pushNode(list, { path: basePath, type: 'depth-limit', required: false });
    return;
  }
  if (schema === null || schema === undefined || typeof schema !== 'object') {
    pushNode(list, { path: basePath, type: 'unknown', required: assumeRequired });
    return;
  }
  if (schema['x-guard-cycle']) {
    pushNode(list, {
      path: basePath,
      type: 'cycle',
      required: assumeRequired,
      cycleRef: schema['x-guard-cycle'],
    });
    return;
  }

  // Composition: allOf merges every branch; oneOf/anyOf flatten to a union of their branches.
  if (schema.allOf && Array.isArray(schema.allOf) && schema.allOf.length) {
    const merged = mergeBranches(schema.allOf, list, basePath, assumeRequired, depth);
    if (schema.properties || schema.type) {
      // Rare: composition alongside own members - treat own members as another branch.
      const own = mergeBranches([omit(schema, 'allOf')], list, basePath, assumeRequired, depth);
      mergeNodes(list, basePath, merged, own);
    }
    return;
  }
  if ((schema.oneOf || schema.anyOf) && Array.isArray(schema.oneOf || schema.anyOf)) {
    const branches = schema.oneOf || schema.anyOf;
    const merged = mergeBranches(branches, list, basePath, assumeRequired, depth);
    mergeNodes(list, basePath, merged, null, { union: true });
    return;
  }

  const requiredList = Array.isArray(schema.required) ? schema.required : [];
  let type = schema.type;
  if (!type && schema.properties) type = 'object';
  if (!type && schema.items) type = 'array';

  pushNode(list, {
    path: basePath,
    type: type || 'any',
    required: assumeRequired,
    enum: Array.isArray(schema.enum) ? schema.enum.map(stringify) : undefined,
    format: schema.format,
    deprecated: schema.deprecated === true || undefined,
    sunset: typeof schema['x-sunset'] === 'string' ? schema['x-sunset'] : undefined,
    additionalPropertiesForbidden: schema.additionalProperties === false || undefined,
  });

  if (type === 'object') {
    const props = schema.properties && typeof schema.properties === 'object' ? schema.properties : {};
    for (const [name, prop] of Object.entries(props)) {
      walk(prop, joinPath(basePath, name), list, requiredList.includes(name), depth + 1);
    }
    if (schema.additionalProperties && typeof schema.additionalProperties === 'object') {
      walk(schema.additionalProperties, joinPath(basePath, '<key>'), list, false, depth + 1);
    }
  } else if (type === 'array') {
    if (schema.items) walk(schema.items, joinPath(basePath, '[]'), list, true, depth + 1);
  }
}

function mergeBranches(branches, list, basePath, assumeRequired, depth) {
  // Flatten each branch in isolation, then merge the per-branch node lists keyed by path.
  const perBranch = [];
  const requiredSets = [];
  for (const branch of branches) {
    const scratch = { __list: [] };
    walk(branch, basePath, scratch.__list, assumeRequired, depth + 1);
    perBranch.push(scratch.__list);
    const req = new Set(
      scratch.__list.filter((n) => n.path === branchPathParent(branch, basePath) && n.required).map((n) => n.path)
    );
    requiredSets.push(req);
  }
  return combineBranchLists(perBranch, requiredSets, basePath);
}

function branchPathParent(branch, basePath) {
  // Root node path of a branch equals basePath.
  return basePath;
}

function combineBranchLists(perBranch, requiredSets, basePath) {
  const byPath = new Map();
  for (let i = 0; i < perBranch.length; i++) {
    for (const node of perBranch[i]) {
      if (!byPath.has(node.path)) byPath.set(node.path, { node, requiredIn: [] });
      if (node.required) byPath.get(node.path).requiredIn.push(i);
    }
  }
  const nodes = [];
  for (const [path, { node, requiredIn }] of byPath) {
    const merged = { ...node };
    if (path === basePath) {
      // Root: required only if required in every branch.
      merged.required = perBranch.every((_, i) => requiredIn.includes(i) || !node.required) && node.required
        ? true : node.required && requiredIn.length === perBranch.length;
    } else {
      merged.required = requiredIn.length === perBranch.length ? true : false;
    }
    nodes.push(merged);
  }
  return nodes;
}

function mergeNodes(list, basePath, primary, secondary, extraMeta) {
  // Attach union/deprecated meta to the root node after branch merging.
  const root = list.find((n) => n.path === basePath);
  if (root) Object.assign(root, extraMeta || {});
  if (secondary && secondary.length) {
    const seen = new Set(list.map((n) => n.path));
    for (const node of secondary) {
      if (!seen.has(node.path)) list.push(node);
      else {
        const existing = list.find((n) => n.path === node.path);
        if (existing && existing.type !== node.type && existing.type !== 'union') existing.type = 'union';
      }
    }
  }
}

function pushNode(list, node) {
  const clean = { ...node };
  for (const k of Object.keys(clean)) if (clean[k] === undefined) delete clean[k];
  if (clean.path === '' && clean.type === 'object') {
    // keep root object node but avoid noisy duplicates
  }
  list.push(clean);
}

function omit(obj, key) {
  const { [key]: dropped, ...rest } = obj;
  return rest;
}

function stringify(v) {
  if (v === null) return 'null';
  if (typeof v === 'object') return JSON.stringify(v);
  return String(v);
}

import { GuardError } from './errors.js';

const HTTP_METHODS = new Set(['get', 'put', 'post', 'delete', 'options', 'head', 'patch', 'trace']);
const MAX_DEPTH = 24;

/**
 * Turn a resolved OpenAPI document into the wire model Contract Guard reasons about:
 *
 *   { title, version, endpoints: [ { key, method, path, internal, deprecated,
 *       pathParams, queryParams, headerParams, cookieParams,
 *       request: { present, required, fields: FieldNode[] },
 *       responses: { '200': { fields: FieldNode[] } } } ] }
 *
 * FieldNode = { path: 'premium.breakdown[].amount', type, required, enum, format,
 *               deprecated, sunset, union }
 *
 * Every `$ref` has already been resolved, so two specs that describe the same contract
 * flatten to the same wire model even when the files are organised completely differently
 * (components renamed, schemas inlined, refs reshuffled). Only the API's actual shape remains.
 */
export function flattenSpec(doc) {
  if (!doc || typeof doc !== 'object' || !doc.paths) {
    throw new GuardError('flatten', 'Document passed to flattener is missing "paths".');
  }

  const endpoints = [];
  for (const [path, pathItem] of Object.entries(doc.paths)) {
    if (!pathItem || typeof pathItem !== 'object') continue;
    const pathInternal = pathItem['x-internal'] === true;
    for (const methodKey of Object.keys(pathItem)) {
      const method = methodKey.toLowerCase();
      if (!HTTP_METHODS.has(method)) continue;
      const op = pathItem[methodKey];
      if (!op || typeof op !== 'object') continue;
      const internal = pathInternal || op['x-internal'] === true;

      const allParams = mergeParams(pathItem.parameters, op.parameters);
      const params = { path: [], query: [], header: [], cookie: [] };
      for (const p of allParams) {
        const location = p.in || 'query';
        if (!params[location]) continue; // unknown location: skipped, surfaced by analysis notes
        params[location].push({
          name: p.name,
          required: location === 'path' ? p.required !== false : p.required === true,
          node:
            flattenSchema(p.schema, p.name, [], location === 'path')[0] || {
              path: p.name,
              type: 'unknown',
              required: true,
            },
        });
      }

      endpoints.push({
        key: `${method.toUpperCase()} ${normalizePath(path)}`,
        method: method.toUpperCase(),
        path,
        pathParams: params.path,
        queryParams: params.query,
        headerParams: params.header,
        cookieParams: params.cookie,
        operationId: op.operationId || null,
        summary: op.summary || null,
        deprecated: op.deprecated === true,
        internal,
        request: flattenRequestBody(op.requestBody),
        responses: flattenResponses(op.responses),
      });
    }
  }

  endpoints.sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
  return {
    title: doc.info?.title || '(untitled)',
    version: doc.info?.version || '(no version)',
    description: doc.info?.description || '',
    openapi: doc.openapi || '',
    endpoints,
  };
}

/** Route-shape normalisation: /quotes/{id} and /quotes/{quoteId} are the same wire route. */
export function normalizePath(path) {
  return String(path).replace(/\{[^/}]*\}/g, '{}');
}

function mergeParams(pathLevel = [], opLevel = []) {
  const out = [];
  const seen = new Set();
  for (const p of [...(opLevel || []), ...(pathLevel || [])]) {
    if (!p || typeof p !== 'object' || !p.name) continue;
    const id = `${p.in}:${p.name}`;
    if (seen.has(id)) continue; // operation-level wins over path-level
    seen.add(id);
    out.push(p);
  }
  return out;
}

function flattenRequestBody(body) {
  if (!body || typeof body !== 'object') return { present: false, required: false, fields: [] };
  const schema = firstContentSchema(body.content);
  return {
    present: true,
    required: body.required === true,
    fields: schema ? flattenSchema(schema, '', [], false) : [],
    schemaless: !schema,
  };
}

function flattenResponses(responses) {
  const out = {};
  if (!responses || typeof responses !== 'object') return out;
  for (const [status, resp] of Object.entries(responses)) {
    if (!resp || typeof resp !== 'object' || status.startsWith('x-')) continue;
    const schema = firstContentSchema(resp.content);
    out[status] = {
      description: resp.description || '',
      fields: schema ? flattenSchema(schema, '', [], false) : [],
      schemaless: !schema,
    };
  }
  return out;
}

/** First application/json schema (fall back to the first content entry with a schema). */
function firstContentSchema(content) {
  if (!content || typeof content !== 'object') return null;
  if (content['application/json']?.schema) return content['application/json'].schema;
  for (const media of Object.values(content)) {
    if (media && typeof media === 'object' && media.schema) return media.schema;
  }
  return null;
}

/** Join a parent wire path with a child segment ('' + name, or parent + '.' + name / '[]'). */
export function joinPath(parent, segment) {
  if (!parent) return segment;
  if (segment === '[]') return `${parent}[]`;
  return `${parent}.${segment}`;
}

/**
 * Flatten one schema into a list of FieldNodes. Root node path is `basePath`.
 * `assumeRequired` marks path parameters, which are required by definition.
 */
export function flattenSchema(schema, basePath, list = [], assumeRequired = false) {
  walk(schema, basePath, list, assumeRequired, 0);
  return list;
}

function walk(schema, basePath, list, assumeRequired, depth) {
  if (depth > MAX_DEPTH) {
    push(list, { path: basePath, type: 'depth-limit', required: assumeRequired });
    return;
  }
  if (schema === null || schema === undefined || typeof schema !== 'object' || Array.isArray(schema)) {
    push(list, { path: basePath, type: 'unknown', required: assumeRequired });
    return;
  }
  if (schema['x-guard-cycle']) {
    push(list, {
      path: basePath,
      type: 'cycle',
      required: assumeRequired,
      cycleRef: schema['x-guard-cycle'],
    });
    return;
  }

  if (schema.allOf && Array.isArray(schema.allOf) && schema.allOf.length) {
    const branches = [...schema.allOf];
    if (hasOwnMembers(schema)) branches.push(ownMembersSchema(schema));
    const merged = mergeBranchLists(
      branches.map((b) => flattenSchema(b, basePath, [], assumeRequired))
    );
    list.push(...merged.nodes);
    if (merged.notes.length) {
      push(list, { path: basePath, type: 'composition-note', required: assumeRequired, note: merged.notes[0] });
    }
    return;
  }
  if (Array.isArray(schema.oneOf) || Array.isArray(schema.anyOf)) {
    const branches = schema.oneOf || schema.anyOf;
    const merged = mergeBranchLists(
      branches.map((b) => flattenSchema(b, basePath, [], assumeRequired))
    );
    for (const node of merged.nodes) {
      if (node.path === basePath) node.union = true;
      list.push(node);
    }
    if (merged.notes.length) {
      push(list, { path: basePath, type: 'composition-note', required: assumeRequired, note: merged.notes[0] });
    }
    return;
  }

  const requiredList = Array.isArray(schema.required) ? schema.required : [];
  let type = schema.type;
  if (!type && schema.properties) type = 'object';
  if (!type && schema.items) type = 'array';

  push(list, {
    path: basePath,
    type: type || 'any',
    required: assumeRequired,
    enum: Array.isArray(schema.enum) ? schema.enum.map(stringify) : undefined,
    format: schema.format,
    deprecated: schema.deprecated === true || undefined,
    sunset: typeof schema['x-sunset'] === 'string' ? schema['x-sunset'] : undefined,
    additionalPropertiesForbidden: schema.additionalProperties === false || undefined,
  });

  if (type === 'object') {
    const props = schema.properties && typeof schema.properties === 'object' ? schema.properties : {};
    for (const [name, prop] of Object.entries(props)) {
      walk(prop, joinPath(basePath, name), list, requiredList.includes(name), depth + 1);
    }
    if (schema.additionalProperties && typeof schema.additionalProperties === 'object') {
      walk(schema.additionalProperties, joinPath(basePath, '<key>'), list, false, depth + 1);
    }
  } else if (type === 'array') {
    if (schema.items) walk(schema.items, joinPath(basePath, '[]'), list, true, depth + 1);
  }
}

const COMPOSITION_KEYS = new Set(['allOf', 'oneOf', 'anyOf', 'not']);
function hasOwnMembers(schema) {
  return Object.keys(schema).some(
    (k) => !COMPOSITION_KEYS.has(k) && !['description', 'title', 'x-sunset'].includes(k)
  );
}
function ownMembersSchema(schema) {
  const out = {};
  for (const [k, v] of Object.entries(schema)) {
    if (!COMPOSITION_KEYS.has(k)) out[k] = v;
  }
  return out;
}

/**
 * Merge independently-flattened branches of a composition:
 * - type differs across branches at the same path -> 'union'
 * - a field is required only if required in every branch
 * - enums/deprecation union across branches
 */
function mergeBranchLists(branchLists) {
  const notes = [];
  const byPath = new Map();
  for (const nodes of branchLists) {
    for (const node of nodes) {
      if (!byPath.has(node.path)) {
        byPath.set(node.path, { base: node, requiredIn: new Set(), enums: [], deprecated: false });
      }
      const entry = byPath.get(node.path);
      if (node.required) entry.requiredIn.add(true);
      entry.enums.push(node.enum);
      if (node.deprecated) entry.deprecated = true;
      if (node.sunset && !entry.sunset) entry.sunset = node.sunset;
    }
  }
  const nodes = [];
  for (const [path, entry] of byPath) {
    const merged = { ...entry.base };
    const types = new Set(branchLists.map((nodes) => nodes.find((n) => n.path === path)?.type).filter(Boolean));
    if (types.size > 1) merged.type = 'union';
    if (entry.deprecated) merged.deprecated = true;
    const enumUnion = dedupe(entry.enums.filter(Boolean).flat());
    if (enumUnion.length) merged.enum = enumUnion;
    if (path === '' || true) {
      // guaranteed presence only when present in every branch
      if (entry.base.required && !branchLists.every((nodes) => nodes.find((n) => n.path === path)?.required)) {
        if (merged.type === 'union') merged.required = entry.requiredIn.size === branchLists.length;
      }
    }
    nodes.push(merged);
  }
  return { nodes, notes };
}

function push(list, node) {
  const clean = { ...node };
  for (const k of Object.keys(clean)) if (clean[k] === undefined) delete clean[k];
  list.push(clean);
}

function dedupe(arr) {
  return [...new Set(arr)];
}

function stringify(v) {
  if (v === null) return 'null';
  if (typeof v === 'object') return JSON.stringify(v);
  return String(v);
}

