/**
 * Severity policy. Every structural change gets exactly one flag:
 *
 *   DANGEROUS   - a correct consumer of the OLD contract can fail against the NEW one.
 *                 (Publishes carrying DANGEROUS changes are stopped.)
 *   WARNING     - may affect consumers depending on how they use it / not guaranteed to break.
 *   DEPRECATED  - nothing breaks yet; a removal is announced (x-sunset date if given).
 *   SAFE        - wire-compatible or purely additive for consumers.
 *
 * Direction matters: relaxing what a server accepts is safe; tightening it is not.
 * Adding to a response is safe; removing from a response is not.
 */

export const SEVERITIES = ['DANGEROUS', 'WARNING', 'DEPRECATED', 'SAFE'];

export function classify(change) {
  const d = change.direction;
  switch (change.kind) {
    case 'endpoint_added':
      return safe('New endpoint; nothing existing depends on it.');

    case 'endpoint_removed':
      return dangerous('Endpoint removed. Every caller still using it will fail.');

    case 'endpoint_deprecated':
      return deprecate(
        change.sunset
          ? `Endpoint deprecated; removal signalled for ${change.sunset}.`
          : 'Endpoint deprecated. Plan a migration before it is removed.'
      );

    case 'status_added':
      return safe(`New response status ${change.status}; consumers simply ignore what they never saw.`);

    case 'status_removed':
      return dangerous(
        `Response status ${change.status} is no longer documented. Clients relying on it lose a documented outcome.`
      );

    case 'body_required_changed': {
      if (change.to === 'required') {
        return dangerous(
          change.from === 'absent'
            ? 'Request body is now required; callers that sent no body will be rejected.'
            : 'Request body became required; callers omitting it will be rejected.'
        );
      }
      return safe('Request body requirement relaxed; every previously valid call stays valid.');
    }

    case 'param_added':
      if (change.required) {
        return dangerous(
          `New required ${change.location} parameter "${change.name}"; every caller must start sending it.`
        );
      }
      return safe(`New optional ${change.location} parameter "${change.name}"; callers may ignore it.`);

    case 'param_removed':
      return safe(
        `${change.location} parameter "${change.name}" no longer documented (acceptance relaxed).`
      );

    case 'param_renamed':
      return safe(
        `Path parameter renamed "${change.from}" -> "${change.to}" at the same position; the URL shape and the value sent over the wire are unchanged.`
      );

    case 'param_requirement_changed':
      if (change.to === 'required') {
        return dangerous(`${change.location} parameter "${change.name}" became required.`);
      }
      return safe(`${change.location} parameter "${change.name}" became optional.`);

    case 'param_type_changed':
      return dangerous(
        `${change.location} parameter "${change.name}" type changed ${change.from} -> ${change.to}; existing callers may send values the new type rejects.`
      );

    case 'field_added': {
      if (d === 'request') {
        if (change.required) {
          return dangerous(
            `New required request field "${change.path}"; callers must send it from now on.`
          );
        }
        return safe('New optional request field; sending it stays optional.');
      }
      return safe('New response field; consumers that ignore unknown fields are unaffected.');
    }

    case 'field_removed': {
      if (d === 'request') {
        if (change.wasRequired) {
          return safe('Required request field removed from the contract (acceptance relaxed).');
        }
        return warning(
          'Optional request field removed from the contract; consumers may still send it and strict providers reject unknown fields.'
        );
      }
      return dangerous(
        'Response field removed; consumers reading it will break.'
      );
    }

    case 'field_requirement_changed': {
      if (d === 'request') {
        if (change.to === 'required') {
          return dangerous(
            `Request field "${change.path}" became required; callers omitting it will be rejected.`
          );
        }
        return safe(`Request field "${change.path}" became optional (relaxation).`);
      }
      if (change.to === 'optional') {
        return warning(
          `Response field "${change.path}" is no longer guaranteed; consumers reading it must handle its absence.`
        );
      }
      return safe(`Response field "${change.path}" is now always present.`);
    }

    case 'field_type_changed':
      return dangerous(
        `"${change.path}" type changed ${change.from} -> ${change.to}; consumers exchanging this value in the old shape will fail.`
      );

    case 'field_enum_changed': {
      const added = change.added || [];
      const removed = change.removed || [];
      if (d === 'request') {
        if (removed.length) {
          return dangerous(
            `Values no longer accepted for "${change.path}": ${removed.join(', ')}. Callers sending them will be rejected.`
          );
        }
        return safe(`New values accepted for "${change.path}": ${added.join(', ')}.`);
      }
      if (added.length) {
        return warning(
          `New values may appear in "${change.path}": ${added.join(', ')}. Consumers with exhaustive handling must cover them.`
        );
      }
      return warning(
        `Values removed from "${change.path}": ${removed.join(', ')}. Consumers depending on seeing them in a flow may misbehave.`
      );
    }

    case 'field_format_changed':
      return warning(`"${change.path}" format changed ${change.from} -> ${change.to}.`);

    case 'field_strictness_changed':
      if (d === 'request') {
        return dangerous(
          `Unknown extra fields are no longer accepted on "${change.path}"; callers sending additional fields will be rejected.`
        );
      }
      return warning(`Unknown extra fields are no longer documented on "${change.path}".`);

    case 'field_deprecated': {
      const base = `"${change.path}" is now deprecated`;
      if (change.sunset) {
        const past = isPast(change.sunset);
        return deprecate(
          `${base}${past ? '; its sunset date has already passed' : `; removal planned for ${change.sunset}`}${change.who ? ` (used by: ${change.who})` : ''}.`
        );
      }
      return deprecate(`${base}; no removal date given.`);
    }

    default:
      return safe('Recognised but unclassified structural change.');
  }
}

function dangerous(note) {
  return { severity: 'DANGEROUS', note };
}
function warning(note) {
  return { severity: 'WARNING', note };
}
function deprecate(note) {
  return { severity: 'DEPRECATED', note };
}
function safe(note) {
  return { severity: 'SAFE', note };
}

function isPast(dateStr) {
  const t = Date.parse(dateStr);
  return Number.isFinite(t) && t < Date.now();
}

/** Aggregate a change list into verdict counts + one-line summary. */
export function summarise(changes) {
  const counts = { DANGEROUS: 0, WARNING: 0, DEPRECATED: 0, SAFE: 0 };
  for (const c of changes) counts[c.severity] = (counts[c.severity] || 0) + 1;
  return counts;
}

/** Wire-path helpers. Paths look like `premium.breakdown[].amount` or `holder.email`. */

/** Path of the parent node: 'a.b[].c' -> 'a.b[]', 'a[]' -> 'a', 'a' -> ''. */
export function parentPath(p) {
  if (!p) return '';
  const i = p.lastIndexOf('.');
  const j = p.lastIndexOf('[]');
  if (j > i) return p.slice(0, j);
  if (i > -1) return p.slice(0, i);
  return '';
}

/** Is `a` the same node as, or an ancestor container of, `b`? */
export function sameOrAncestor(a, b) {
  if (!a) return true;
  if (a === b) return true;
  return b.startsWith(`${a}.`) || b.startsWith(`${a}[]`);
}

/** Keep only the topmost paths: drop any path that has a proper ancestor in the set. */
export function pruneToTopmost(paths) {
  const list = [...paths];
  return list.filter((p) => !list.some((q) => q !== p && sameOrAncestor(q, p)));
}

/** First segment of a path (used for quick bucketing). */
export function rootOf(p) {
  const i = p.indexOf('.');
  const j = p.indexOf('[]');
  if (j > -1 && (i === -1 || j < i)) return p.slice(0, j);
  return i === -1 ? p : p.slice(0, i);
}

import { classify } from './rules.js';
import { sameOrAncestor, pruneToTopmost } from './pathutils.js';

/**
 * Compare two flattened wire models and produce the change list.
 * Changes are structural facts (what moved on the wire); severities come from rules.js.
 *
 * Endpoint identity = HTTP method + normalised route shape, so renaming a path
 * parameter or reshuffling components never creates phantom endpoints.
 */
export function diffSpecs(oldFlat, newFlat) {
  const changes = [];
  const oldEndpoints = new Map(oldFlat.endpoints.map((e) => [e.key, e]));
  const newEndpoints = new Map(newFlat.endpoints.map((e) => [e.key, e]));

  for (const [key, ep] of oldEndpoints) {
    if (!newEndpoints.has(key)) {
      changes.push(mk({ kind: 'endpoint_removed', direction: 'endpoint', endpoint: key, endpointKey: key, internal: ep.internal }));
      continue;
    }
    const next = newEndpoints.get(key);
    diffEndpoint(ep, next, changes);
  }
  for (const [key, ep] of newEndpoints) {
    if (!oldEndpoints.has(key)) {
      changes.push(
        mk({ kind: 'endpoint_added', direction: 'endpoint', endpoint: key, endpointKey: key, internal: ep.internal })
      );
    }
  }

  for (const c of changes) {
    const { severity, note } = classify(c);
    c.severity = severity;
    c.note = note;
  }
  changes.sort(byLocationThenSeverity);
  return changes;
}

function diffEndpoint(oldEp, newEp, changes) {
  const label = `${newEp.method} ${newEp.path}`;
  const common = { endpoint: label, endpointKey: newEp.key, internal: newEp.internal };

  if (newEp.deprecated && !oldEp.deprecated) {
    changes.push(mk({ kind: 'endpoint_deprecated', direction: 'endpoint', ...common }));
  }

  diffParams(oldEp, newEp, common, changes);
  diffBody(oldEp, newEp, common, changes);
  diffResponses(oldEp, newEp, common, changes);
}

/* ---------------------------------- parameters ---------------------------------- */

function diffParams(oldEp, newEp, common, changes) {
  // Path parameters are matched by position: the wire URL shape only cares about
  // how many `{}` slots exist and what must be sent in them, not their documentation name.
  const maxLen = Math.max(oldEp.pathParams.length, newEp.pathParams.length);
  for (let i = 0; i < maxLen; i++) {
    const a = oldEp.pathParams[i];
    const b = newEp.pathParams[i];
    if (a && !b) {
      changes.push(mk({ kind: 'param_removed', direction: 'request', location: 'path', name: a.name, ...common }));
    } else if (!a && b) {
      changes.push(
        mk({ kind: 'param_added', direction: 'request', location: 'path', name: b.name, required: b.required, ...common })
      );
    } else if (a && b) {
      if (a.name !== b.name) {
        changes.push(
          mk({ kind: 'param_renamed', direction: 'request', location: 'path', from: a.name, to: b.name, ...common })
        );
      }
      diffParamNode(a, b, common, changes);
    }
  }

  // Query/header/cookie parameters are matched by name within their location.
  diffParamList(oldEp.queryParams, newEp.queryParams, 'query', common, changes);
  diffParamList(oldEp.headerParams, newEp.headerParams, 'header', common, changes);
  diffParamList(oldEp.cookieParams, newEp.cookieParams, 'cookie', common, changes);
}

function diffParamList(oldList, newList, location, common, changes) {
  const oldMap = new Map(oldList.map((p) => [p.name, p]));
  const newMap = new Map(newList.map((p) => [p.name, p]));
  for (const [name, p] of oldMap) {
    if (!newMap.has(name)) {
      changes.push(mk({ kind: 'param_removed', direction: 'request', location, name, ...common }));
      continue;
    }
    const q = newMap.get(name);
    if (p.required !== q.required) {
      changes.push(
        mk({
          kind: 'param_requirement_changed',
          direction: 'request',
          location,
          name,
          from: p.required ? 'required' : 'optional',
          to: q.required ? 'required' : 'optional',
          ...common,
        })
      );
    }
    diffParamNode(p, q, common, changes);
  }
  for (const [name, p] of newMap) {
    if (!oldMap.has(name)) {
      changes.push(
        mk({ kind: 'param_added', direction: 'request', location, name, required: p.required, ...common })
      );
    }
  }
}

function diffParamNode(a, b, common, changes) {
  const at = normType(a.node?.type);
  const bt = normType(b.node?.type);
  if (at !== bt && !compatibleTypes(at, bt)) {
    changes.push(
      mk({
        kind: 'param_type_changed',
        direction: 'request',
        location: a.location || 'param',
        name: a.name,
        from: at,
        to: bt,
        ...common,
      })
    );
  }
  const ae = (a.node?.enum || []).map(String).sort();
  const be = (b.node?.enum || []).map(String).sort();
  if (ae.length && be.length && !sameList(ae, be)) {
    changes.push(
      mk({
        kind: 'field_enum_changed',
        direction: 'request',
        path: a.name,
        added: be.filter((x) => !ae.includes(x)),
        removed: ae.filter((x) => !be.includes(x)),
        param: true,
        ...common,
      })
    );
  }
}

/* ------------------------------- request & responses ------------------------------ */

function diffBody(oldEp, newEp, common, changes) {
  const o = oldEp.request;
  const n = newEp.request;
  const oldState = !o.present ? 'absent' : o.required ? 'required' : 'optional';
  const newState = !n.present ? 'absent' : n.required ? 'required' : 'optional';
  if (oldState !== newState) {
    changes.push(mk({ kind: 'body_required_changed', direction: 'request', from: oldState, to: newState, ...common }));
  }
  if (o.present && n.present && o.fields.length && n.fields.length) {
    diffFieldTree(o.fields, n.fields, 'request', undefined, common, changes);
  } else if (o.present && n.present && !o.fields.length && n.fields.length) {
    // old body schemaless, new typed: additive documentation, safe.
    changes.push(mk({ kind: 'field_added', direction: 'request', path: '(body schema documented)', required: false, ...common, severityOverride: 'SAFE' }));
  } else if (o.present && n.present && o.fields.length && !n.fields.length) {
    changes.push(
      mk({ kind: 'field_removed', direction: 'request', path: '(body schema removed)', wasRequired: false, ...common, severityOverride: 'WARNING' })
    );
  }
}

function diffResponses(oldEp, newEp, common, changes) {
  const oldStatuses = new Set(Object.keys(oldEp.responses));
  const newStatuses = new Set(Object.keys(newEp.responses));
  for (const status of oldStatuses) {
    if (!newStatuses.has(status)) {
      changes.push(mk({ kind: 'status_removed', direction: 'response', status, ...common }));
      continue;
    }
    const o = oldEp.responses[status];
    const n = newEp.responses[status];
    if (o.fields.length && n.fields.length) {
      diffFieldTree(o.fields, n.fields, 'response', status, common, changes);
    }
  }
  for (const status of newStatuses) {
    if (!oldStatuses.has(status)) {
      changes.push(mk({ kind: 'status_added', direction: 'response', status, ...common }));
    }
  }
}

/* ---------------------------------- field trees ---------------------------------- */

function diffFieldTree(oldFields, newFields, direction, status, common, changes) {
  const statusPart = status ? `response ${status}` : 'request body';
  const oldMap = new Map(oldFields.map((n) => [n.path, n]));
  const newMap = new Map(newFields.map((n) => [n.path, n]));

  // Prune to topmost removed/added nodes so restructuring a subtree reports one clear change.
  const removedPaths = pruneToTopmost(
    [...oldMap.keys()].filter((p) => !newMap.has(p))
  );
  const addedPaths = pruneToTopmost([...newMap.keys()].filter((p) => !oldMap.has(p)));

  for (const p of removedPaths) {
    const node = oldMap.get(p);
    changes.push(
      mk({
        kind: 'field_removed',
        direction,
        path: p,
        wasRequired: !!node.required,
        locationLabel: statusPart,
        ...common,
      })
    );
  }
  for (const p of addedPaths) {
    const node = newMap.get(p);
    changes.push(
      mk({
        kind: 'field_added',
        direction,
        path: p,
        required: !!node.required,
        locationLabel: statusPart,
        ...common,
      })
    );
  }

  for (const [p, a] of oldMap) {
    const b = newMap.get(p);
    if (!b) continue;
    const changed = diffNode(a, b, direction, statusPart, common, changes);
    if (!changed && a.path === '' ) {
      // root unchanged: nothing to do
    }
  }
}

function diffNode(a, b, direction, statusPart, common, changes) {
  const at = normType(a.type);
  const bt = normType(b.type);
  let changed = false;
  if (at !== bt && !compatibleTypes(at, bt) && a.path !== '') {
    changes.push(
      mk({
        kind: 'field_type_changed',
        direction,
        path: a.path,
        from: at,
        to: bt,
        locationLabel: statusPart,
        ...common,
      })
    );
    changed = true;
  }
  if (a.required !== b.required && a.path !== '') {
    changes.push(
      mk({
        kind: 'field_requirement_changed',
        direction,
        path: a.path,
        from: a.required ? 'required' : 'optional',
        to: b.required ? 'required' : 'optional',
        locationLabel: statusPart,
        ...common,
      })
    );
    changed = true;
  }
  const ae = (a.enum || []).map(String);
  const be = (b.enum || []).map(String);
  if ((ae.length || be.length) && !sameList(ae, be)) {
    changes.push(
      mk({
        kind: 'field_enum_changed',
        direction,
        path: a.path || '(root)',
        added: be.filter((x) => !ae.includes(x)),
        removed: ae.filter((x) => !be.includes(x)),
        locationLabel: statusPart,
        ...common,
      })
    );
    changed = true;
  }
  const af = a.format || null;
  const bf = b.format || null;
  if (af !== bf && (af || bf)) {
    changes.push(
      mk({
        kind: 'field_format_changed',
        direction,
        path: a.path || '(root)',
        from: af || '(none)',
        to: bf || '(none)',
        locationLabel: statusPart,
        ...common,
      })
    );
    changed = true;
  }
  if (b.deprecated && !a.deprecated) {
    changes.push(
      mk({
        kind: 'field_deprecated',
        direction,
        path: a.path || '(root)',
        sunset: b.sunset,
        locationLabel: statusPart,
        ...common,
      })
    );
    changed = true;
  } else if (b.deprecated && a.deprecated && b.sunset && b.sunset !== a.sunset) {
    changes.push(
      mk({
        kind: 'field_deprecated',
        direction,
        path: a.path || '(root)',
        sunset: b.sunset,
        sunsetChanged: true,
        locationLabel: statusPart,
        ...common,
      })
    );
    changed = true;
  }
  if (!!a.additionalPropertiesForbidden !== !!b.additionalPropertiesForbidden && a.path !== '') {
    changes.push(
      mk({
        kind: 'field_strictness_changed',
        direction,
        path: a.path,
        from: a.additionalPropertiesForbidden ? 'closed' : 'open',
        to: b.additionalPropertiesForbidden ? 'closed' : 'open',
        locationLabel: statusPart,
        ...common,
      })
    );
    changed = true;
  }
  return changed;
}

/* ------------------------------------ helpers ------------------------------------ */

function mk(change) {
  if (change.severityOverride) {
    change.severity = change.severityOverride;
    change.note = change.note || 'Structural change (documented for completeness).';
  }
  return change;
}

function normType(t) {
  return t || 'any';
}

/** Types we never flag: unknown/any on either side, or identical unions of primitives. */
function compatibleTypes(a, b) {
  const loose = new Set(['any', 'unknown', 'depth-limit', 'cycle']);
  if (loose.has(a) || loose.has(b)) return true;
  // integer/number are wire-compatible enough to keep noise down? No - they are NOT.
  return false;
}

function sameList(a, b) {
  if (a.length !== b.length) return false;
  const sa = [...a].sort();
  const sb = [...b].sort();
  return sa.every((v, i) => v === sb[i]);
}

function byLocationThenSeverity(a, b) {
  const sevRank = { DANGEROUS: 0, WARNING: 1, DEPRECATED: 2, SAFE: 3 };
  if ((a.endpointKey || '').localeCompare(b.endpointKey || '') !== 0) {
    return (a.endpointKey || '').localeCompare(b.endpointKey || '');
  }
  if (sevRank[a.severity] !== sevRank[b.severity]) return sevRank[a.severity] - sevRank[b.severity];
  return (a.path || a.name || '').localeCompare(b.path || b.name || '');
}

/** Build a human-readable location label for a change. */
export function changeLocation(change) {
  const base = change.endpoint || change.endpointKey || '';
  if (change.kind === 'endpoint_removed' || change.kind === 'endpoint_added' || change.kind === 'endpoint_deprecated') {
    return base + (change.internal ? '  [internal]' : '');
  }
  let loc = `${base} · ${change.locationLabel || (change.direction === 'request' ? 'request' : 'response')}`;
  if (change.param) loc = `${base} · parameter ${change.path}`;
  else if (change.location) loc = `${base} · ${change.location} param ${change.name}`;
  else if (change.path) loc = `${loc} · ${change.path}`;
  if (change.internal) loc += '  [internal]';
  return loc;
}

