import { parseYaml } from './lib/yaml.js';
import { validateSpec, resolveRefs } from './lib/openapi.js';
import { flattenSpec, normalizePath } from './lib/flatten.js';
import { diffSpecs, changeLocation } from './lib/diff.js';
import { summarise } from './lib/rules.js';
import { computeImpact } from './lib/impact.js';
import { asGuardError } from './lib/errors.js';

/**
 * Full analysis pipeline for a candidate spec against a baseline (or nothing for v1):
 *   parse -> validate -> resolve refs -> flatten to wire model -> diff -> classify -> impact.
 *
 * Throws GuardError on any stage failure; the caller turns that into a failed
 * publish attempt (fail safe: we never pass a spec we could not fully understand).
 */
export function analyse(candidateText, baselineFlat, usages) {
  const doc = validateSpec(parseYaml(candidateText));
  const resolved = resolveRefs(doc);
  const flat = flattenSpec(resolved);

  const changes = baselineFlat ? diffSpecs(baselineFlat, flat) : [];
  const counts = summarise(changes);

  // Prepare usages with route keys for endpoint matching.
  const preparedUsages = (usages || []).map((u) => ({
    ...u,
    routeKey: normalizePath(u.path),
    pathParamNames: extractPathParams(u.path),
  }));

  const endpointKeys = new Map(flat.endpoints.map((e) => [e.key, e]));
  const impact = computeImpact(changes, preparedUsages, endpointKeys);

  const dangerous = changes.filter((c) => c.severity === 'DANGEROUS');
  const verdict = {
    status: dangerous.length ? 'BLOCKED' : 'PUBLISHED_OK',
    reason:
      dangerous.length
        ? `${dangerous.length} dangerous change${dangerous.length === 1 ? '' : 's'} found`
        : 'no dangerous changes',
    counts,
    affectedConsumers: impact.consumers,
    dangerous,
  };

  return { flat, changes, counts, impact, verdict };
}

/** Human-readable summary used in API responses and webhook payloads. */
export function humanSummary(context) {
  const { serviceName, fromVersion, toVersion, counts, verdict, changes } = context;
  const top = changes
    .filter((c) => c.severity !== 'SAFE')
    .slice(0, 6)
    .map((c) => `- [${c.severity}] ${changeLocation(c)}: ${c.note}`);
  const lines = [
    `Contract Guard: ${serviceName} ${fromVersion ? `${fromVersion} -> ` : ''}${toVersion}`,
    `Verdict: ${verdict.status} (${counts.DANGEROUS} dangerous / ${counts.WARNING} warning / ${counts.DEPRECATED} deprecated / ${counts.SAFE} safe)`,
    verdict.affectedConsumers.length
      ? `Affected consumers: ${verdict.affectedConsumers.map((c) => c.consumer).join(', ')}`
      : 'Affected consumers: none registered',
    top.length ? top.join('\n') : '- no notable changes',
  ];
  return lines.join('\n');
}

function extractPathParams(path) {
  const out = [];
  const re = /\{([^/}]+)\}/g;
  let m;
  while ((m = re.exec(String(path)))) out.push(m[1]);
  return out;
}

export { asGuardError };

/**
 * Engine tests against the real kit specs/consumers.
 * Run: npm run test:engine   (no DB or server needed)
 *
 * These encode the expected Contract Guard verdicts for every planted scenario:
 * reorganisation fidelity, broken $ref fail-safe, deprecations, removals,
 * required additions, enum narrowing and response-field optionalisation.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import yaml from 'js-yaml';
import { analyse } from '../src/analyse.js';
import { GuardError } from '../src/lib/errors.js';

const KIT_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');

function loadSpec(rel) {
  return fs.readFileSync(path.join(KIT_ROOT, rel), 'utf8');
}

function loadUsages(provider) {
  const dir = path.join(KIT_ROOT, 'consumers');
  const usages = [];
  for (const file of fs.readdirSync(dir).filter((f) => f.endsWith('.yaml'))) {
    const doc = yaml.load(fs.readFileSync(path.join(dir, file), 'utf8'));
    for (const u of doc.uses || []) {
      if (u.provider === provider) {
        usages.push({
          consumer: doc.consumer,
          team: doc.team,
          method: String(u.method || '').toUpperCase(),
          path: u.path,
          sends: (u.sends || []).map(String),
          reads: (u.reads || []).map(String),
          provider,
        });
      }
    }
  }
  return usages;
}

function baseline(rel) {
  const { flat } = analyse(loadSpec(rel), null, []);
  return flat;
}

function changeKeys(res) {
  return new Set(res.changes.filter((c) => c.severity !== 'SAFE').map((c) => `${c.severity}:${c.kind}:${c.path || c.name || ''}@${c.endpointKey}`));
}

/* ------------------------------ quote-api ------------------------------ */

test('quote-api 1 -> 2: pure reorganisation is fully SAFE (only the path-param rename)', () => {
  const res = analyse(loadSpec('specs/quote-api/2-reorganised.yaml'), baseline('specs/quote-api/1-initial.yaml'), loadUsages('quote-api'));
  assert.equal(res.verdict.status, 'PUBLISHED_OK');
  assert.equal(res.counts.DANGEROUS, 0);
  assert.equal(res.counts.WARNING, 0);
  const nonSafe = res.changes.filter((c) => c.severity !== 'SAFE');
  assert.deepEqual(nonSafe, []);
  assert.equal(res.changes.length, 1, 'exactly the parameter rename should be reported');
  assert.equal(res.changes[0].kind, 'param_renamed');
  assert.deepEqual(res.verdict.affectedConsumers, []);
});

test('quote-api 2 -> 3: blocked; breakdown[].amount removal hits mobile-app; required region param; EXPIRED enum warns', () => {
  const res = analyse(loadSpec('specs/quote-api/3-price-lines.yaml'), baseline('specs/quote-api/2-reorganised.yaml'), loadUsages('quote-api'));
  assert.equal(res.verdict.status, 'BLOCKED');
  assert.equal(res.counts.DANGEROUS, 2);
  assert.equal(res.counts.WARNING, 1);

  const amount = res.changes.find((c) => c.kind === 'field_removed' && c.path === 'premium.breakdown[].amount');
  assert.ok(amount, 'amount removal must be detected');
  assert.equal(amount.severity, 'DANGEROUS');
  assert.ok(amount.affected.some((a) => a.consumer === 'mobile-app'), 'mobile-app reads breakdown[].amount');

  const region = res.changes.find((c) => c.kind === 'param_added' && c.name === 'region');
  assert.ok(region && region.severity === 'DANGEROUS');
  assert.equal(region.internal, true, 'region endpoint is x-internal');
  assert.deepEqual(region.affected, [], 'no consumer uses the internal endpoint');

  const enumChange = res.changes.find((c) => c.kind === 'field_enum_changed' && c.path === 'status');
  assert.ok(enumChange && enumChange.severity === 'WARNING');
  assert.deepEqual(enumChange.added, ['EXPIRED']);

  const valueAdd = res.changes.find((c) => c.kind === 'field_added' && c.path === 'premium.breakdown[].value');
  assert.ok(valueAdd && valueAdd.severity === 'SAFE');
});

test('quote-api 3 -> 4: only optional additions (SAFE) when comparing against the attempted v2', () => {
  const res = analyse(loadSpec('specs/quote-api/4-ncb-and-taxes.yaml'), baseline('specs/quote-api/3-price-lines.yaml'), loadUsages('quote-api'));
  assert.equal(res.verdict.status, 'PUBLISHED_OK');
  const nonSafe = res.changes.filter((c) => c.severity !== 'SAFE');
  assert.deepEqual(nonSafe, []);
  const ncb = res.changes.find((c) => c.path === 'rider.ncbPercent');
  const taxes = res.changes.find((c) => c.path === 'premium.taxes');
  assert.ok(ncb && taxes, 'both new optional fields detected');
});

test('quote-api: retrying v2.1.0 while v2.0.0 was never published still blocks (diffs against current 1.1.0)', () => {
  const res = analyse(loadSpec('specs/quote-api/4-ncb-and-taxes.yaml'), baseline('specs/quote-api/2-reorganised.yaml'), loadUsages('quote-api'));
  assert.equal(res.verdict.status, 'BLOCKED');
  assert.equal(res.counts.DANGEROUS, 2);
});

/* ------------------------------ policy-api ------------------------------ */

test('policy-api 1 -> 2: deprecations only; legacyCode deprecation flags payments-svc; past sunset noted', () => {
  const res = analyse(loadSpec('specs/policy-api/2-deprecations.yaml'), baseline('specs/policy-api/1-initial.yaml'), loadUsages('policy-api'));
  assert.equal(res.verdict.status, 'PUBLISHED_OK');
  assert.equal(res.counts.DANGEROUS, 0);
  assert.equal(res.counts.WARNING, 0);
  assert.equal(res.counts.DEPRECATED, 2);

  const legacy = res.changes.find((c) => c.path === 'legacyCode');
  assert.ok(legacy && legacy.severity === 'DEPRECATED');
  assert.ok(legacy.affected.some((a) => a.consumer === 'payments-svc'), 'payments-svc reads legacyCode');
  assert.match(legacy.note, /sunset date has already passed/, 'x-sunset 2026-11-01 is in the past');

  const phone = res.changes.find((c) => c.path === 'holder.phone');
  assert.ok(phone && phone.severity === 'DEPRECATED');
  assert.match(phone.note, /2027-06-30/);
  assert.deepEqual(phone.affected, [], 'no consumer reads holder.phone');
});

test('policy-api 2 -> 3: blocked; legacyCode removal hits payments-svc; phone removal has no consumer impact', () => {
  const res = analyse(loadSpec('specs/policy-api/3-remove-old-fields.yaml'), baseline('specs/policy-api/2-deprecations.yaml'), loadUsages('policy-api'));
  assert.equal(res.verdict.status, 'BLOCKED');
  assert.equal(res.counts.DANGEROUS, 2);

  const legacy = res.changes.find((c) => c.kind === 'field_removed' && c.path === 'legacyCode');
  assert.ok(legacy);
  assert.ok(legacy.affected.some((a) => a.consumer === 'payments-svc'));

  const phone = res.changes.find((c) => c.kind === 'field_removed' && c.path === 'holder.phone');
  assert.ok(phone);
  assert.deepEqual(phone.affected, []);
});

test('policy-api 3 -> 4 (vs still-current 1.1.0): blocked with 4 dangerous findings incl. partner-portal impact', () => {
  const res = analyse(loadSpec('specs/policy-api/4-endorsement-rules.yaml'), baseline('specs/policy-api/2-deprecations.yaml'), loadUsages('policy-api'));
  assert.equal(res.verdict.status, 'BLOCKED');
  assert.equal(res.counts.DANGEROUS, 4);

  const enumChange = res.changes.find((c) => c.kind === 'field_enum_changed' && c.path === 'type');
  assert.ok(enumChange);
  assert.deepEqual(enumChange.removed, ['VEHICLE']);
  assert.ok(enumChange.affected.some((a) => a.consumer === 'partner-portal'), 'partner-portal sends type');

  const req = res.changes.find((c) => c.kind === 'field_added' && c.path === 'requestedBy');
  assert.ok(req && req.severity === 'DANGEROUS');
  assert.ok(req.affected.some((a) => a.consumer === 'partner-portal'));
});

/* ------------------------------ claims-api ------------------------------ */

test('claims-api 2: broken $ref must fail the analysis (fail-safe, stage resolve)', () => {
  assert.throws(
    () => analyse(loadSpec('specs/claims-api/2-channel-and-notes.yaml'), baseline('specs/claims-api/1-initial.yaml'), loadUsages('claims-api')),
    (err) => err instanceof GuardError && err.stage === 'resolve' && /ClaimDocumnt/.test(err.message)
  );
});

test('claims-api 3 (fixed): same version publishes cleanly with only SAFE changes', () => {
  const res = analyse(loadSpec('specs/claims-api/3-channel-and-notes-fixed.yaml'), baseline('specs/claims-api/1-initial.yaml'), loadUsages('claims-api'));
  assert.equal(res.verdict.status, 'PUBLISHED_OK');
  assert.deepEqual(changeKeys(res), new Set());
  assert.ok(res.changes.some((c) => c.path === 'channel'));
  assert.ok(res.changes.some((c) => c.path === 'assessorNotes'));
});

test('claims-api 4: amountApproved no longer guaranteed -> WARNING hitting mobile-app; 202 response is SAFE', () => {
  const res = analyse(loadSpec('specs/claims-api/4-approval-later.yaml'), baseline('specs/claims-api/3-channel-and-notes-fixed.yaml'), loadUsages('claims-api'));
  assert.equal(res.verdict.status, 'PUBLISHED_OK');
  assert.equal(res.counts.DANGEROUS, 0);
  assert.equal(res.counts.WARNING, 1);

  const req = res.changes.find((c) => c.kind === 'field_requirement_changed' && c.path === 'amountApproved');
  assert.ok(req && req.severity === 'WARNING');
  assert.equal(req.to, 'optional');
  assert.ok(req.affected.some((a) => a.consumer === 'mobile-app'));

  const added = res.changes.find((c) => c.kind === 'status_added' && c.status === '202');
  assert.ok(added && added.severity === 'SAFE');
});

/* ------------------------------ unit-ish checks ------------------------------ */

test('endpoint matching normalises route shapes: consumer /quotes/{id} connects to /quotes/{quoteId}', () => {
  const res = analyse(loadSpec('specs/quote-api/2-reorganised.yaml'), baseline('specs/quote-api/1-initial.yaml'), loadUsages('quote-api'));
  // If matching failed, the safe param rename would still pass, so assert via a breaking case instead:
  const breaking = analyse(loadSpec('specs/quote-api/3-price-lines.yaml'), baseline('specs/quote-api/2-reorganised.yaml'), loadUsages('quote-api'));
  const amount = breaking.changes.find((c) => c.path === 'premium.breakdown[].amount');
  const affectedRoutes = amount.affected.map((a) => a.usage);
  assert.ok(affectedRoutes.includes('POST /quotes'), 'POST /quotes usage matched');
  assert.ok(
    breaking.changes.some((c) => c.endpointKey === 'GET /quotes/{}' && c.affected?.length === 0),
    'renamed param route still maps consumers but no reads/sends break there'
  );
});

test('first version publish (no baseline) yields no changes', () => {
  const res = analyse(loadSpec('specs/quote-api/1-initial.yaml'), null, loadUsages('quote-api'));
  assert.equal(res.changes.length, 0);
  assert.equal(res.verdict.status, 'PUBLISHED_OK');
});

test('unresolvable external $ref fails too', () => {
  const spec = loadSpec('specs/quote-api/1-initial.yaml').replace(
    "'#/components/schemas/Vehicle'",
    "'https://example.com/schemas/Vehicle.json'"
  );
  assert.throws(() => analyse(spec, null, []), (err) => err instanceof GuardError && err.stage === 'resolve');
});

test('invalid YAML fails with stage parse', () => {
  assert.throws(() => analyse('paths: [unclosed', null, []), (err) => err instanceof GuardError && err.stage === 'parse');
});

test('document missing info.version fails with stage validate', () => {
  const spec = 'openapi: 3.0.3\ninfo:\n  title: X\npaths: {}\n';
  assert.throws(() => analyse(spec, null, []), (err) => err instanceof GuardError && err.stage === 'validate');
});

