test('quote-api 2 -> 3: blocked; breakdown[].amount removal hits mobile-app; required region param; EXPIRED enum warns', () => {
  const res = analyse(loadSpec('specs/quote-api/3-price-lines.yaml'), baseline('specs/quote-api/2-reorganised.yaml'), loadUsages('quote-api'));
  assert.equal(res.verdict.status, 'BLOCKED');
  assert.equal(res.counts.DANGEROUS, 3, 'amount removed from both Quote-returning responses + region param');
  assert.equal(res.counts.WARNING, 2, 'EXPIRED enum widening on both Quote responses');

  const amountChanges = res.changes.filter((c) => c.kind === 'field_removed' && c.path === 'premium.breakdown[].amount');
  assert.equal(amountChanges.length, 2, 'removal reported per response that returns Quote');
  const postAmount = amountChanges.find((c) => c.endpointKey === 'POST /quotes');
  assert.ok(postAmount);
  assert.equal(postAmount.severity, 'DANGEROUS');
  assert.ok(postAmount.affected.some((a) => a.consumer === 'mobile-app'), 'mobile-app reads breakdown[].amount');

  const region = res.changes.find((c) => c.kind === 'param_added' && c.name === 'region');
  assert.ok(region && region.severity === 'DANGEROUS');
  assert.equal(region.internal, true, 'region endpoint is x-internal');
  assert.deepEqual(region.affected, [], 'no consumer uses the internal endpoint');

  const enumChanges = res.changes.filter((c) => c.kind === 'field_enum_changed' && c.path === 'status');
  assert.ok(enumChanges.length === 2 && enumChanges.every((c) => c.severity === 'WARNING'));
  assert.deepEqual(enumChanges[0].added, ['EXPIRED']);

  const valueAdd = res.changes.find((c) => c.kind === 'field_added' && c.path === 'premium.breakdown[].value');
  assert.ok(valueAdd && valueAdd.severity === 'SAFE');
});

