test('policy-api 1 -> 2: deprecations only; legacyCode deprecation flags payments-svc; past sunset noted', () => {
  const res = analyse(loadSpec('specs/policy-api/2-deprecations.yaml'), baseline('specs/policy-api/1-initial.yaml'), loadUsages('policy-api'));
  assert.equal(res.verdict.status, 'PUBLISHED_OK');
  assert.equal(res.counts.DANGEROUS, 0);
  assert.equal(res.counts.WARNING, 0);
  assert.equal(res.counts.DEPRECATED, 4, 'Policy fields deprecated: reported per response that returns Policy');

  const legacyChanges = res.changes.filter((c) => c.path === 'legacyCode');
  assert.ok(legacyChanges.length >= 1 && legacyChanges.every((c) => c.severity === 'DEPRECATED'));
  const perPolicyLegacy = legacyChanges.find((c) => c.endpointKey === 'GET /policies/{policyId}');
  assert.ok(perPolicyLegacy.affected.some((a) => a.consumer === 'payments-svc'), 'payments-svc reads legacyCode');
  assert.match(perPolicyLegacy.note, /sunset date has already passed/, 'x-sunset 2026-11-01 is in the past');

  const phoneChanges = res.changes.filter((c) => c.path === 'holder.phone');
  assert.ok(phoneChanges.length >= 1);
  assert.match(phoneChanges[0].note, /2027-06-30/);
  assert.ok(phoneChanges.every((c) => c.affected.length === 0), 'no consumer reads holder.phone');
});

test('policy-api 2 -> 3: blocked; legacyCode removal hits payments-svc; phone removal has no consumer impact', () => {
  const res = analyse(loadSpec('specs/policy-api/3-remove-old-fields.yaml'), baseline('specs/policy-api/2-deprecations.yaml'), loadUsages('policy-api'));
  assert.equal(res.verdict.status, 'BLOCKED');
  assert.equal(res.counts.DANGEROUS, 4, 'legacyCode and holder.phone removed, reported per returning endpoint');

  const legacyChanges = res.changes.filter((c) => c.kind === 'field_removed' && c.path === 'legacyCode');
  assert.equal(legacyChanges.length, 2);
  const perPolicy = legacyChanges.find((c) => c.endpointKey === 'GET /policies/{policyId}');
  assert.ok(perPolicy.affected.some((a) => a.consumer === 'payments-svc'));

  const phoneChanges = res.changes.filter((c) => c.kind === 'field_removed' && c.path === 'holder.phone');
  assert.equal(phoneChanges.length, 2);
  assert.ok(phoneChanges.every((c) => c.affected.length === 0));
});

