import pg from 'pg';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const SCHEMA_SQL = fs.readFileSync(path.join(path.dirname(fileURLToPath(import.meta.url)), 'schema.sql'), 'utf8');

let pool;

export function getPool() {
  if (!pool) {
    pool = new pg.Pool({ connectionString: process.env.DATABASE_URL, max: 10 });
    pool.on('error', (err) => console.error('[db] idle client error:', err.message));
  }
  return pool;
}

export async function query(text, params) {
  return getPool().query(text, params);
}

/** Ensure the schema exists. Idempotent. */
export async function initSchema() {
  await query(SCHEMA_SQL);
}

export async function close() {
  if (pool) await pool.end();
}

/** Transaction helper: fn receives a client; commits on success, rolls back on throw. */
export async function withTx(fn) {
  const client = await getPool().connect();
  try {
    await client.query('BEGIN');
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    try {
      await client.query('ROLLBACK');
    } catch {
      /* rollback already failed - nothing more to do */
    }
    throw err;
  } finally {
    client.release();
  }
}

export const config = {
  port: Number(process.env.PORT || 3000),
  databaseUrl: process.env.DATABASE_URL || 'postgres://guard:guard@localhost:5432/contractguard',
  webhookUrl: process.env.WEBHOOK_URL || '',
  publicUrl: process.env.PUBLIC_URL || '',
  seedDir: process.env.SEED_DIR || '',
  seedOnBoot: process.env.SEED_ON_BOOT !== '0',
};

export const SEVERITY_ORDER = { DANGEROUS: 0, WARNING: 1, DEPRECATED: 2, SAFE: 3 };

import { config } from './config.js';
import { query } from './db.js';

/**
 * Fire-and-forget webhook notification (chat/email stand-in from the kit).
 * Never blocks or fails the pipeline: delivery problems are logged in the
 * notifications table so the UI can show whether the platform leads were told.
 */
export async function notify(event, payload) {
  if (!config.webhookUrl) return { sent: false, reason: 'WEBHOOK_URL not configured' };
  const body = JSON.stringify({ event, sent_at: new Date().toISOString(), ...payload });
  let statusCode = null;
  let error = null;
  try {
    const res = await fetch(config.webhookUrl, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body,
      signal: AbortSignal.timeout(5000),
    });
    statusCode = res.status;
    if (!res.ok) error = `webhook responded ${res.status}`;
  } catch (err) {
    error = err?.message || String(err);
  }
  try {
    await query('INSERT INTO notifications (attempt_id, event, url, status_code, error) VALUES ($1,$2,$3,$4,$5)', [
      payload.attempt_id ?? null,
      event,
      config.webhookUrl,
      statusCode,
      error,
    ]);
  } catch (dbErr) {
    console.error('[notify] could not record notification:', dbErr.message);
  }
  if (error) console.error(`[notify] ${event} delivery problem: ${error}`);
  return { sent: !error, status_code: statusCode, error };
}

import { query, withTx } from '../db.js';
import { analyse, humanSummary } from '../analyse.js';
import { GuardError, asGuardError } from '../lib/errors.js';
import { notify } from '../notify.js';

/**
 * The publish pipeline. Everything a publish attempt does lives here so the API
 * layer stays thin:
 *
 *   load service -> analyse candidate vs current version (parse/validate/resolve/
 *   flatten/diff/classify) -> compute consumer impact -> record attempt ->
 *   publish the version or stop it -> notify the webhook (chat/email stand-in).
 *
 * Failure policy (fail safe): any analysis error records an ERROR attempt and
 * refuses the publish. The caller is told exactly which stage failed. Nothing is
 * ever silently passed.
 */

export class HttpError extends Error {
  constructor(status, message, extra) {
    super(message);
    this.status = status;
    this.extra = extra;
  }
}

export async function loadServiceBySlug(slug) {
  const { rows } = await query('SELECT * FROM services WHERE slug = $1', [slug]);
  return rows[0];
}

async function currentFlat(serviceId) {
  const { rows } = await query(
    `SELECT v.flat, v.version
       FROM services s JOIN versions v ON v.id = s.current_version_id
      WHERE s.id = $1`,
    [serviceId]
  );
  return rows[0] || null;
}

async function usagesForProvider(serviceId) {
  const { rows } = await query(
    `SELECT c.slug AS consumer, c.team, u.method, u.path, u.sends, u.reads
       FROM consumer_usages u
       JOIN consumers c ON c.id = u.consumer_id
      WHERE u.provider_service_id = $1`,
    [serviceId]
  );
  return rows.map((r) => ({
    consumer: r.consumer,
    team: r.team,
    method: r.method,
    path: r.path,
    sends: r.sends || [],
    reads: r.reads || [],
  }));
}

/** Dry run: full analysis, nothing recorded, nothing sent. */
export async function previewPublish(service, yamlText) {
  const cur = await currentFlat(service.id);
  const usages = await usagesForProvider(service.id);
  const result = runAnalysis(yamlText, cur, usages);
  return {
    service: service.slug,
    from_version: cur?.version || null,
    to_version: result.flat.version,
    would_be: result.verdict.status === 'PUBLISHED_OK' ? 'PUBLISHED' : 'BLOCKED',
    status: result.verdict.status,
    reason: result.verdict.reason,
    counts: result.counts,
    changes: result.changes,
    impact: { consumers: result.impact.consumers, unmatched: result.impact.unmatched },
    summary: humanSummary({
      serviceName: service.name,
      fromVersion: cur?.version || null,
      toVersion: result.flat.version,
      counts: result.counts,
      verdict: result.verdict,
      changes: result.changes,
    }),
    preview: true,
  };
}

/** Real publish: analyse, record attempt, publish or stop, notify. */
export async function publish(service, yamlText) {
  const cur = await currentFlat(service.id);
  const fromVersion = cur?.version || null;
  const usages = await usagesForProvider(service.id);

  let analysis;
  let failure = null;
  try {
    analysis = runAnalysis(yamlText, cur, usages);
  } catch (err) {
    const guardErr = asGuardError('analysis', err);
    failure = guardErr;
  }

  if (failure) {
    // Fail safe: we could not fully understand the spec, so nothing is published.
    const attempt = await recordFailedAttempt(service, fromVersion, yamlText, failure);
    await notifyPublishEvent('publish.failed', service, fromVersion, null, attempt, failure);
    throw new HttpError(422, `Publish refused: ${failure.message}`, {
      attempt_id: attempt.id,
      status: 'ERROR',
      stage: failure.stage,
      error: failure.message,
      brokenRefs: failure.detail?.brokenRefs,
      problems: failure.detail?.problems,
    });
  }

  const { flat, changes, counts, impact, verdict } = analysis;
  const blocked = verdict.status === 'BLOCKED';

  const attempt = await withTx(async (client) => {
    const attemptNoRow = await client.query(
      'SELECT COALESCE(MAX(attempt_no),0)+1 AS n FROM publish_attempts WHERE service_id = $1',
      [service.id]
    );
    const attemptNo = attemptNoRow.rows[0].n;

    const inserted = await client.query(
      `INSERT INTO publish_attempts
         (service_id, attempt_no, from_version, to_version, status, counts, changes, impact, raw)
       VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)
       RETURNING *`,
      [
        service.id,
        attemptNo,
        fromVersion,
        flat.version,
        blocked ? 'BLOCKED' : 'PUBLISHED',
        counts,
        JSON.stringify(changes),
        JSON.stringify({ consumers: impact.consumers, unmatched: impact.unmatched }),
        yamlText,
      ]
    );
    const attemptRow = inserted.rows[0];

    let versionRow = null;
    if (!blocked) {
      // Version already registered? (e.g. exact same version string republished)
      const dup = await client.query('SELECT id, version FROM versions WHERE service_id = $1 AND version = $2', [
        service.id,
        flat.version,
      ]);
      if (dup.rows.length) {
        throw new HttpError(409, `Version ${flat.version} is already registered for ${service.slug}.`, {
          version_id: dup.rows[0].id,
        });
      }
      const revRow = await client.query(
        'SELECT COALESCE(MAX(revision),0)+1 AS r FROM versions WHERE service_id = $1',
        [service.id]
      );
      const versionInserted = await client.query(
        `INSERT INTO versions (service_id, version, revision, spec, flat, changes, counts, impact, attempt_id)
         VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING *`,
        [
          service.id,
          flat.version,
          revRow.rows[0].r,
          JSON.stringify(flat.spec ?? null),
          JSON.stringify(flat),
          JSON.stringify(changes),
          counts,
          JSON.stringify({ consumers: impact.consumers, unmatched: impact.unmatched }),
          attemptRow.id,
        ]
      );
      versionRow = versionInserted.rows[0];
      await client.query('UPDATE services SET current_version_id = $1 WHERE id = $2', [versionRow.id, service.id]);
      await client.query('UPDATE publish_attempts SET to_version = $1 WHERE id = $2', [flat.version, attemptRow.id]);
    }
    return { attempt: attemptRow, version: versionRow };
  });

  const payload = await notifyPublishEvent(blocked ? 'publish.blocked' : 'publish.succeeded', service, fromVersion, flat.version, {
    id: attempt.attempt.id,
    counts,
    impact: { consumers: impact.consumers },
  });

  return {
    attempt_id: attempt.attempt.id,
    status: blocked ? 'BLOCKED' : 'PUBLISHED',
    reason: verdict.reason,
    service: service.slug,
    from_version: fromVersion,
    to_version: flat.version,
    version_id: attempt.version?.id ?? null,
    counts,
    changes,
    impact: { consumers: impact.consumers, unmatched: impact.unmatched },
    summary: humanSummary({
      serviceName: service.name,
      fromVersion,
      toVersion: flat.version,
      counts,
      verdict,
      changes,
    }),
    notified: payload.sent !== false,
    notification: payload,
  };
}

function runAnalysis(yamlText, current, usages) {
  // analyse() throws GuardError on parse/validate/resolve problems.
  return analyse(yamlText, current ? current.flat : null, usages);
}

async function recordFailedAttempt(service, fromVersion, yamlText, guardErr) {
  const { rows } = await query(
    `INSERT INTO publish_attempts
       (service_id, attempt_no, from_version, to_version, status, error_stage, error_message, raw)
     VALUES ($1, (SELECT COALESCE(MAX(attempt_no),0)+1 FROM publish_attempts WHERE service_id = $2),
             $3, NULL, 'ERROR', $4, $5, $6)
     RETURNING *`,
    [service.id, service.id, fromVersion, guardErr.stage, guardErr.message, yamlText]
  );
  return rows[0];
}

async function notifyPublishEvent(event, service, fromVersion, toVersion, attemptLike, failure) {
  const counts = attemptLike.counts || {};
  const consumers = attemptLike.impact?.consumers || [];
  const summary = failure
    ? [
        `Contract Guard: ${service.name} publish ${fromVersion ? `${fromVersion} -> ` : ''}${toVersion || '(unknown)'} FAILED`,
        `Stage: ${failure.stage}. ${failure.message}`,
        'The publish was refused (fail safe): the guard could not verify this spec.',
      ].join('\n')
    : [
        `Contract Guard: ${service.name} ${fromVersion ? `${fromVersion} -> ` : ''}${toVersion} ${event === 'publish.blocked' ? 'BLOCKED' : 'published'}`,
        `${counts.DANGEROUS || 0} dangerous / ${counts.WARNING || 0} warning / ${counts.DEPRECATED || 0} deprecated / ${counts.SAFE || 0} safe`,
        consumers.length ? `Affected consumers: ${consumers.map((c) => c.consumer).join(', ')}` : 'Affected consumers: none registered',
      ].join('\n');

  return notify(event, {
    service: service.slug,
    service_name: service.name,
    from_version: fromVersion,
    to_version: toVersion,
    attempt_id: attemptLike.id,
    status: event === 'publish.succeeded' ? 'PUBLISHED' : event === 'publish.blocked' ? 'BLOCKED' : 'ERROR',
    counts,
    affected_consumers: consumers.map((c) => c.consumer),
    summary,
  });
}

/** Diff any two published versions of a service (uses current consumer registrations). */
export async function diffVersions(service, fromVersion, toVersion) {
  const { rows } = await query(
    'SELECT version, flat FROM versions WHERE service_id = $1 AND version IN ($2,$3)',
    [service.id, fromVersion, toVersion]
  );
  const map = new Map(rows.map((r) => [r.version, r.flat]));
  if (!map.has(fromVersion)) throw new HttpError(404, `Version ${fromVersion} of ${service.slug} not found.`);
  if (!map.has(toVersion)) throw new HttpError(404, `Version ${toVersion} of ${service.slug} not found.`);
  const usages = await usagesForProvider(service.id);
  const result = runAnalysisBetween(map.get(fromVersion), map.get(toVersion), usages);
  return {
    service: service.slug,
    from_version: fromVersion,
    to_version: toVersion,
    counts: result.counts,
    verdict: result.verdict.status,
    reason: result.verdict.reason,
    changes: result.changes,
    impact: { consumers: result.impact.consumers, unmatched: result.impact.unmatched },
  };
}

function runAnalysisBetween(fromFlat, toFlat, usages) {
  // Both sides are already validated flats from the registry; diff + impact only.
  const { diffSpecs } = diffModule;
  const { summarise } = rulesModule;
  const changes = diffSpecs(fromFlat, toFlat);
  const counts = summarise(changes);
  const prepared = usages.map((u) => ({
    ...u,
    routeKey: u.path.replace(/\{[^/}]*\}/g, '{}'),
    pathParamNames: [...String(u.path).matchAll(/\{([^/}]+)\}/g)].map((m) => m[1]),
  }));
  const impact = impactModule.computeImpact(changes, prepared, toFlat.endpoints);
  const dangerous = changes.filter((c) => c.severity === 'DANGEROUS');
  return {
    changes,
    counts,
    impact,
    verdict: {
      status: dangerous.length ? 'BLOCKED' : 'PUBLISHED_OK',
      reason: dangerous.length ? `${dangerous.length} dangerous changes` : 'no dangerous changes',
    },
  };
}

import * as diffModule from '../lib/diff.js';
import * as rulesModule from '../lib/rules.js';
import * as impactModule from '../lib/impact.js';

