input.content:
import { query, withTx } from '../db.js';
import { analyse, humanSummary } from '../analyse.js';
import { asGuardError } from '../lib/errors.js';
import { diffSpecs } from '../lib/diff.js';
import { summarise } from '../lib/rules.js';
import { computeImpact } from '../lib/impact.js';
import { notify } from '../notify.js';

/**
 * The publish pipeline. Everything a publish attempt does lives here so the API
 * layer stays thin:
 *
 *   load service -> analyse candidate vs current version (parse/validate/resolve/
 *   flatten/diff/classify) -> compute consumer impact -> record attempt ->
 *   publish the version or stop it -> notify the webhook (chat/email stand-in).
 *
 * Failure policy (fail safe): any analysis error records an ERROR attempt and
 * refuses the publish. The caller is told exactly which stage failed. Nothing is
 * ever silently passed.
 */

export class HttpError extends Error {
  constructor(status, message, extra) {
    super(message);
    this.status = status;
    this.extra = extra;
  }
}

export async function loadServiceBySlug(slug) {
  const { rows } = await query('SELECT * FROM services WHERE slug = $1', [slug]);
  return rows[0];
}

async function currentFlat(serviceId) {
  const { rows } = await query(
    `SELECT v.flat, v.version
       FROM services s JOIN versions v ON v.id = s.current_version_id
      WHERE s.id = $1`,
    [serviceId]
  );
  return rows[0] || null;
}

async function usagesForProvider(serviceId) {
  const { rows } = await query(
    `SELECT c.slug AS consumer, c.team, u.method, u.path, u.sends, u.reads
       FROM consumer_usages u
       JOIN consumers c ON c.id = u.consumer_id
      WHERE u.provider_service_id = $1`,
    [serviceId]
  );
  return rows.map((r) => ({
    consumer: r.consumer,
    team: r.team,
    method: r.method,
    path: r.path,
    sends: r.sends || [],
    reads: r.reads || [],
  }));
}

function prepareUsages(usages) {
  return usages.map((u) => ({
    ...u,
    routeKey: String(u.path).replace(/\{[^/}]*\}/g, '{}'),
    pathParamNames: [...String(u.path).matchAll(/\{([^/}]+)\}/g)].map((m) => m[1]),
  }));
}

/** Dry run: full analysis, nothing recorded, nothing sent. */
export async function previewPublish(service, yamlText) {
  const cur = await currentFlat(service.id);
  const usages = await usagesForProvider(service.id);
  const result = analyse(yamlText, cur ? cur.flat : null, usages);
  return {
    service: service.slug,
    from_version: cur?.version || null,
    to_version: result.flat.version,
    would_be: result.verdict.status === 'PUBLISHED_OK' ? 'PUBLISHED' : 'BLOCKED',
    status: result.verdict.status,
    reason: result.verdict.reason,
    counts: result.counts,
    changes: result.changes,
    impact: { consumers: result.impact.consumers, unmatched: result.impact.unmatched },
    summary: humanSummary({
      serviceName: service.name,
      fromVersion: cur?.version || null,
      toVersion: result.flat.version,
      counts: result.counts,
      verdict: result.verdict,
      changes: result.changes,
    }),
    preview: true,
  };
}

/** Real publish: analyse, record attempt, publish or stop, notify. */
export async function publish(service, yamlText) {
  const cur = await currentFlat(service.id);
  const fromVersion = cur?.version || null;
  const usages = await usagesForProvider(service.id);

  let analysis;
  let failure = null;
  try {
    analysis = analyse(yamlText, cur ? cur.flat : null, usages);
  } catch (err) {
    failure = asGuardError('analysis', err);
  }

  if (failure) {
    // Fail safe: we could not fully understand the spec, so nothing is published.
    const attempt = await recordFailedAttempt(service, fromVersion, yamlText, failure);
    await notifyFailure(service, fromVersion, attempt.id, failure);
    throw new HttpError(422, `Publish refused: ${failure.message}`, {
      attempt_id: attempt.id,
      status: 'ERROR',
      stage: failure.stage,
      error: failure.message,
      brokenRefs: failure.detail?.brokenRefs,
      problems: failure.detail?.problems,
    });
  }

  const { doc, flat, changes, counts, impact, verdict } = analysis;
  const blocked = verdict.status === 'BLOCKED';

  const { attempt, version } = await withTx(async (client) => {
    const attemptNoRow = await client.query(
      'SELECT COALESCE(MAX(attempt_no),0)+1 AS n FROM publish_attempts WHERE service_id = $1',
      [service.id]
    );
    const inserted = await client.query(
      `INSERT INTO publish_attempts
         (service_id, attempt_no, from_version, to_version, status, counts, changes, impact, raw)
       VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)
       RETURNING *`,
      [
        service.id,
        attemptNoRow.rows[0].n,
        fromVersion,
        flat.version,
        blocked ? 'BLOCKED' : 'PUBLISHED',
        counts,
        JSON.stringify(changes),
        JSON.stringify({ consumers: impact.consumers, unmatched: impact.unmatched }),
        yamlText,
      ]
    );
    const attemptRow = inserted.rows[0];

    if (blocked) return { attempt: attemptRow, version: null };

    // Version already registered? (exact same version string republished)
    const dup = await client.query('SELECT id FROM versions WHERE service_id = $1 AND version = $2', [
      service.id,
      flat.version,
    ]);
    if (dup.rows.length) {
      throw new HttpError(409, `Version ${flat.version} is already registered for ${service.slug}.`, {
        already_registered: true,
      });
    }

    const revRow = await client.query('SELECT COALESCE(MAX(revision),0)+1 AS r FROM versions WHERE service_id = $1', [
      service.id,
    ]);
    const versionInserted = await client.query(
      `INSERT INTO versions (service_id, version, revision, spec, flat, changes, counts, impact, attempt_id)
       VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING *`,
      [
        service.id,
        flat.version,
        revRow.rows[0].r,
        JSON.stringify(doc),
        JSON.stringify(flat),
        JSON.stringify(changes),
        counts,
        JSON.stringify({ consumers: impact.consumers, unmatched: impact.unmatched }),
        attemptRow.id,
      ]
    );
    const versionRow = versionInserted.rows[0];
    await client.query('UPDATE services SET current_version_id = $1 WHERE id = $2', [versionRow.id, service.id]);
    return { attempt: attemptRow, version: versionRow };
  });

  const event = blocked ? 'publish.blocked' : 'publish.succeeded';
  const notification = await notifyPublishEvent(event, service, fromVersion, flat.version, {
    id: attempt.id,
    counts,
    impact: { consumers: impact.consumers },
  });

  return {
    attempt_id: attempt.id,
    status: blocked ? 'BLOCKED' : 'PUBLISHED',
    reason: verdict.reason,
    service: service.slug,
    from_version: fromVersion,
    to_version: flat.version,
    version_id: version?.id ?? null,
    counts,
    changes,
    impact: { consumers: impact.consumers, unmatched: impact.unmatched },
    summary: humanSummary({
      serviceName: service.name,
      fromVersion,
      toVersion: flat.version,
      counts,
      verdict,
      changes,
    }),
    notified: notification.sent !== false,
  };
}

function runDiff(fromFlat, toFlat, usages) {
  const changes = diffSpecs(fromFlat, toFlat);
  const counts = summarise(changes);
  const impact = computeImpact(changes, prepareUsages(usages), toFlat.endpoints);
  const dangerous = changes.filter((c) => c.severity === 'DANGEROUS');
  return {
    changes,
    counts,
    impact,
    verdict: {
      status: dangerous.length ? 'BLOCKED' : 'PUBLISHED_OK',
      reason: dangerous.length ? `${dangerous.length} dangerous change${dangerous.length === 1 ? '' : 's'}` : 'no dangerous changes',
    },
  };
}

/** Diff any two published versions of a service (uses current consumer registrations). */
export async function diffVersions(service, fromVersion, toVersion) {
  const { rows } = await query('SELECT version, flat FROM versions WHERE service_id = $1 AND version = ANY($2)', [
    service.id,
    [fromVersion, toVersion],
  ]);
  const map = new Map(rows.map((r) => [r.version, r.flat]));
  if (!map.has(fromVersion)) throw new HttpError(404, `Version ${fromVersion} of ${service.slug} not found.`);
  if (!map.has(toVersion)) throw new HttpError(404, `Version ${toVersion} of ${service.slug} not found.`);
  const usages = await usagesForProvider(service.id);
  const result = runDiff(map.get(fromVersion), map.get(toVersion), usages);
  return {
    service: service.slug,
    from_version: fromVersion,
    to_version: toVersion,
    counts: result.counts,
    verdict: result.verdict.status,
    reason: result.verdict.reason,
    changes: result.changes,
    impact: { consumers: result.impact.consumers, unmatched: result.impact.unmatched },
  };
}

async function recordFailedAttempt(service, fromVersion, yamlText, guardErr) {
  const { rows } = await query(
    `INSERT INTO publish_attempts
       (service_id, attempt_no, from_version, to_version, status, error_stage, error_message, raw)
     VALUES ($1, (SELECT COALESCE(MAX(attempt_no),0)+1 FROM publish_attempts WHERE service_id = $2),
             $3, NULL, 'ERROR', $4, $5, $6)
     RETURNING *`,
    [service.id, service.id, fromVersion, guardErr.stage, guardErr.message, yamlText]
  );
  return rows[0];
}

async function notifyPublishEvent(event, service, fromVersion, toVersion, attemptLike) {
  const counts = attemptLike.counts || {};
  const consumers = attemptLike.impact?.consumers || [];
  const summary = [
    `Contract Guard: ${service.name} ${fromVersion ? `${fromVersion} -> ` : ''}${toVersion} ${event === 'publish.blocked' ? 'BLOCKED' : 'published'}`,
    `${counts.DANGEROUS || 0} dangerous / ${counts.WARNING || 0} warning / ${counts.DEPRECATED || 0} deprecated / ${counts.SAFE || 0} safe`,
    consumers.length
      ? `Affected consumers: ${consumers.map((c) => c.consumer).join(', ')}`
      : 'Affected consumers: none registered',
  ].join('\n');

  return notify(event, {
    service: service.slug,
    service_name: service.name,
    from_version: fromVersion,
    to_version: toVersion,
    attempt_id: attemptLike.id,
    status: event === 'publish.succeeded' ? 'PUBLISHED' : 'BLOCKED',
    counts,
    affected_consumers: consumers.map((c) => c.consumer),
    summary,
  });
}

async function notifyFailure(service, fromVersion, attemptId, failure) {
  const summary = [
    `Contract Guard: ${service.name} publish from ${fromVersion || '(first version)'} FAILED`,
    `Stage: ${failure.stage}. ${failure.message}`,
    'The publish was refused (fail safe): the guard could not verify this spec.',
  ].join('\n');
  return notify('publish.failed', {
    service: service.slug,
    service_name: service.name,
    from_version: fromVersion,
    to_version: null,
    attempt_id: attemptId,
    status: 'ERROR',
    stage: failure.stage,
    error: failure.message,
    summary,
  });
}

import { query } from '../db.js';
import { HttpError } from './publish.js';

const SLUG_RE = /^[a-z0-9][a-z0-9._-]{1,62}$/;
const METHODS = new Set(['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'HEAD', 'OPTIONS', 'ANY']);

/* --------------------------------- services --------------------------------- */

export async function registerService({ slug, name, owner_team, owner_contact, description }) {
  if (!SLUG_RE.test(slug || '')) throw new HttpError(400, 'slug must be lowercase letters/digits/dots/dashes (2-63 chars).');
  if (!name || typeof name !== 'string') throw new HttpError(400, 'name is required.');
  if (!owner_team || typeof owner_team !== 'string') throw new HttpError(400, 'owner_team is required.');
  try {
    const { rows } = await query(
      `INSERT INTO services (slug, name, owner_team, owner_contact, description)
       VALUES ($1,$2,$3,$4,$5) RETURNING *`,
      [slug, name, owner_team, owner_contact || null, description || null]
    );
    return rows[0];
  } catch (err) {
    if (err.code === '23505') throw new HttpError(409, `Service "${slug}" is already registered.`);
    throw err;
  }
}

export async function listServices() {
  const { rows } = await query(
    `SELECT s.*,
            cv.version AS current_version,
            (SELECT COUNT(*)::int FROM versions v WHERE v.service_id = s.id) AS version_count,
            (SELECT COUNT(*)::int FROM consumer_usages u WHERE u.provider_service_id = s.id) AS usage_count,
            (SELECT COUNT(*)::int FROM consumer_usages u JOIN consumers c ON c.id = u.consumer_id
              WHERE u.provider_service_id = s.id) - COUNT(DISTINCT c2.slug) AS _,
            la.status AS last_attempt_status, la.created_at AS last_attempt_at,
            la.counts AS last_counts
       FROM services s
       LEFT JOIN versions cv ON cv.id = s.current_version_id
       LEFT JOIN LATERAL (
         SELECT * FROM publish_attempts pa WHERE pa.service_id = s.id ORDER BY pa.attempt_no DESC LIMIT 1
       ) la ON true
       LEFT JOIN LATERAL (
         SELECT DISTINCT c.slug FROM consumer_usages u JOIN consumers c ON c.id = u.consumer_id
          WHERE u.provider_service_id = s.id LIMIT 1
       ) c2 ON true
      ORDER BY s.slug`
  );
  // usage_count counts usages; distinct consumer count computed separately for clarity
  const distinct = await query(
    `SELECT provider_service_id AS sid, COUNT(DISTINCT consumer_id)::int AS n
       FROM consumer_usages GROUP BY provider_service_id`
  );
  const distinctMap = new Map(distinct.rows.map((r) => [r.sid, r.n]));
  return rows.map((r) => ({ ...r, consumer_count: distinctMap.get(r.id) || 0, _: undefined }));
}

export async function getServiceDetail(slug) {
  const { rows } = await query('SELECT * FROM services WHERE slug = $1', [slug]);
  const service = rows[0];
  if (!service) throw new HttpError(404, `Service "${slug}" not found.`);

  const versions = await query(
    'SELECT id, version, revision, counts, created_at, attempt_id FROM versions WHERE service_id = $1 ORDER BY revision',
    [service.id]
  );
  const attempts = await query(
    `SELECT id, attempt_no, from_version, to_version, status, counts, error_stage, error_message,
            impact, notified, created_at
       FROM publish_attempts WHERE service_id = $1 ORDER BY attempt_no DESC`,
    [service.id]
  );
  const usages = await query(
    `SELECT u.id, u.method, u.path, u.sends, u.reads, u.note, u.created_at,
            c.slug AS consumer, c.team AS consumer_team, c.slug AS consumer_slug
       FROM consumer_usages u JOIN consumers c ON c.id = u.consumer_id
      WHERE u.provider_service_id = $1
      ORDER BY c.slug, u.method, u.path`,
    [service.id]
  );
  const currentFlatRows = await query('SELECT flat, spec, version FROM versions WHERE id = $1', [
    service.current_version_id || -1,
  ]);
  const current = currentFlatRows.rows[0] || null;

  return { service, versions: versions.rows, attempts: attempts.rows, usages: usages.rows, current };
}

/* --------------------------------- consumers --------------------------------- */

export async function registerConsumer({ slug, name, team, contact }) {
  if (!SLUG_RE.test(slug || '')) throw new HttpError(400, 'slug must be lowercase letters/digits/dots/dashes (2-63 chars).');
  if (!name || typeof name !== 'string') throw new HttpError(400, 'name is required.');
  if (!team || typeof team !== 'string') throw new HttpError(400, 'team is required.');
  try {
    const { rows } = await query(
      'INSERT INTO consumers (slug, name, team, contact) VALUES ($1,$2,$3,$4) RETURNING *',
      [slug, name, team, contact || null]
    );
    return rows[0];
  } catch (err) {
    if (err.code === '23505') throw new HttpError(409, `Consumer "${slug}" is already registered.`);
    throw err;
  }
}

export async function listConsumers() {
  const { rows } = await query(
    `SELECT c.*,
            (SELECT COUNT(*)::int FROM consumer_usages u WHERE u.consumer_id = c.id) AS usage_count
       FROM consumers c ORDER BY c.slug`
  );
  const usages = await query(
    `SELECT u.id, u.consumer_id, u.method, u.path, u.sends, u.reads, u.note,
            s.slug AS provider, s.name AS provider_name
       FROM consumer_usages u JOIN services s ON s.id = u.provider_service_id
      ORDER BY s.slug, u.method, u.path`
  );
  const byConsumer = new Map();
  for (const u of usages.rows) {
    if (!byConsumer.has(u.consumer_id)) byConsumer.set(u.consumer_id, []);
    byConsumer.get(u.consumer_id).push(u);
  }
  return rows.map((r) => ({ ...r, usages: byConsumer.get(r.id) || [] }));
}

export async function registerUsage(consumerSlug, { provider, method, path, sends, reads, note }) {
  const consumer = (await query('SELECT * FROM consumers WHERE slug = $1', [consumerSlug])).rows[0];
  if (!consumer) throw new HttpError(404, `Consumer "${consumerSlug}" not found.`);
  const service = (await query('SELECT * FROM services WHERE slug = $1', [provider])).rows[0];
  if (!service) throw new HttpError(404, `Provider service "${provider}" not found. Register it first.`);
  const m = String(method || '').toUpperCase();
  if (!METHODS.has(m)) throw new HttpError(400, `method must be one of ${[...METHODS].join(', ')}.`);
  if (!path || !String(path).startsWith('/')) throw new HttpError(400, 'path must start with "/".');
  for (const [label, arr] of [['sends', sends], ['reads', reads]]) {
    if (arr !== undefined && (!Array.isArray(arr) || arr.some((x) => typeof x !== 'string'))) {
      throw new HttpError(400, `${label} must be an array of field paths (strings).`);
    }
  }
  const { rows } = await query(
    `INSERT INTO consumer_usages (consumer_id, provider_service_id, method, path, sends, reads, note)
     VALUES ($1,$2,$3,$4,$5,$6,$7)
     ON CONFLICT (consumer_id, provider_service_id, method, path)
     DO UPDATE SET sends = EXCLUDED.sends, reads = EXCLUDED.reads, note = EXCLUDED.note
     RETURNING *`,
    [consumer.id, service.id, m, path, JSON.stringify(sends || []), JSON.stringify(reads || []), note || null]
  );
  return rows[0];
}

export async function deleteUsage(usageId) {
  const { rows } = await query('DELETE FROM consumer_usages WHERE id = $1 RETURNING id', [usageId]);
  if (!rows.length) throw new HttpError(404, 'Usage not found.');
  return { deleted: rows[0].id };
}

/* ---------------------------------- metrics ---------------------------------- */

export async function metrics() {
  const counts = await query(`
    SELECT
      (SELECT COUNT(*)::int FROM services) AS services,
      (SELECT COUNT(*)::int FROM consumers) AS consumers,
      (SELECT COUNT(*)::int FROM consumer_usages) AS usages,
      (SELECT COUNT(*)::int FROM versions) AS versions,
      (SELECT COUNT(*)::int FROM publish_attempts) AS attempts,
      (SELECT COUNT(*)::int FROM publish_attempts WHERE status = 'PUBLISHED') AS published,
      (SELECT COUNT(*)::int FROM publish_attempts WHERE status = 'BLOCKED') AS blocked,
      (SELECT COUNT(*)::int FROM publish_attempts WHERE status = 'ERROR') AS errors
  `);

  const attempts = await query(
    `SELECT pa.id, pa.status, pa.from_version, pa.to_version, pa.counts, pa.error_stage,
            pa.error_message, pa.created_at, s.slug AS service, s.name AS service_name
       FROM publish_attempts pa JOIN services s ON s.id = pa.service_id
      ORDER BY pa.created_at DESC, pa.id DESC LIMIT 12`
  );

  const severityTotals = { DANGEROUS: 0, WARNING: 0, DEPRECATED: 0, SAFE: 0 };
  const sevRows = await query(`SELECT counts FROM publish_attempts WHERE status <> 'ERROR'`);
  for (const r of sevRows.rows) {
    for (const k of Object.keys(severityTotals)) severityTotals[k] += r.counts?.[k] || 0;
  }

  const affected = await query(
    `SELECT imp->'consumers' AS consumers, s.slug AS service
       FROM publish_attempts pa JOIN services s ON s.id = pa.service_id
      WHERE status <> 'ERROR'`
  );
  const perConsumer = new Map();
  for (const row of affected.rows) {
    for (const c of row.consumers || []) {
      const key = c.consumer;
      if (!perConsumer.has(key)) perConsumer.set(key, { consumer: key, team: c.team, findings: 0 });
      perConsumer.get(key).findings += c.findings?.length || 0;
    }
  }

  const perService = await query(
    `SELECT s.slug, s.name, s.owner_team,
            cv.version AS current_version,
            (SELECT COUNT(*)::int FROM versions v WHERE v.service_id = s.id) AS versions,
            (SELECT COUNT(*)::int FROM publish_attempts pa WHERE pa.service_id = s.id AND pa.status = 'BLOCKED') AS blocked_attempts,
            (SELECT COUNT(*)::int FROM consumer_usages u WHERE u.provider_service_id = s.id) AS usages
       FROM services s
       LEFT JOIN versions cv ON cv.id = s.current_version_id
      ORDER BY s.slug`
  );

  const unmatched = await query(
    `SELECT COUNT(*)::int AS n FROM consumer_usages u
       WHERE NOT EXISTS (
         SELECT 1 FROM versions v
          WHERE v.service_id = u.provider_service_id
            AND v.flat::text LIKE '%'
       )`
  );
  // Unmatched is computed properly in JS below (route shapes), keep SQL cheap.
  const usageRows = await query(
    `SELECT s.slug AS provider, u.method, u.path, c.slug AS consumer, c.team
       FROM consumer_usages u
       JOIN services s ON s.id = u.provider_service_id
       JOIN consumers c ON c.id = u.consumer_id`
  );
  const currentFlats = await query(
    `SELECT s.id AS sid, v.flat FROM services s LEFT JOIN versions v ON v.id = s.current_version_id`
  );
  const flatsBySid = new Map(currentFlats.rows.map((r) => [r.sid, r.flat]));
  const unmatchedList = [];
  for (const u of usageRows.rows) {
    const flat = flatsBySid.get(u.provider);
    const shape = String(u.path).replace(/\{[^/}]*\}/g, '{}');
    const matched = flat?.endpoints?.some((e) => e.method === u.method && e.path.replace(/\{[^/}]*\}/g, '{}') === shape);
    if (!matched) unmatchedList.push({ consumer: u.consumer, team: u.team, usage: `${u.method} ${u.path}`, provider: u.provider });
  }

  return {
    totals: counts.rows[0],
    severityTotals,
    affectedConsumersTop: [...perConsumer.values()].sort((a, b) => b.findings - a.findings),
    recentAttempts: attempts.rows,
    perService: perService.rows,
    unmatchedUsages: unmatchedList,
  };
}

export async function recentEvents() {
  const { rows } = await query(
    `SELECT n.id, n.event, n.url, n.status_code, n.error, n.created_at,
            pa.id AS attempt_id, s.slug AS service
       FROM notifications n
       LEFT JOIN publish_attempts pa ON pa.id = n.attempt_id
       LEFT JOIN services s ON s.id = pa.service_id
      ORDER BY n.id DESC LIMIT 30`
  );
  return rows;
}

