         SELECT * FROM publish_attempts pa WHERE pa.service_id = s.id ORDER BY pa.attempt_no DESC LIMIT 1
       ) la ON true
       LEFT JOIN LATERAL (
         SELECT DISTINCT c.slug FROM consumer_usages u JOIN consumers c ON c.id = u.consumer_id
          WHERE u.provider_service_id = s.id LIMIT 1
       ) c2 ON true
      ORDER BY s.slug`
  );
  // usage_count counts usages; distinct consumer count computed separately for clarity
  const distinct = await query(
    `SELECT provider_service_id AS sid, COUNT(DISTINCT consumer_id)::int AS n
       FROM consumer_usages GROUP BY provider_service_id`
  );
  const distinctMap = new Map(distinct.rows.map((r) => [r.sid, r.n]));
  return rows.map((r) => ({ ...r, consumer_count: distinctMap.get(r.id) || 0, _: undefined }));
}

