import fs from 'node:fs';
import path from 'node:path';
import yaml from 'js-yaml';
import { query } from './db.js';
import { registerService, registerConsumer, registerUsage } from './services/registry.js';
import { publish } from './services/publish.js';
import { config } from './config.js';

/**
 * First-boot import of the starter kit: registers the three provider services with
 * their owners, replays every spec version through the real publish pipeline (so
 * attempts, verdicts, changelog and notifications all exist), then registers the
 * consumer services and what they use.
 *
 * Publish order matters: all first versions, then consumers, then the remaining
 * versions - so impact analysis has consumers registered before the changes that
 * would affect them.
 */
export async function seedIfEmpty() {
  if (!config.seedDir || !config.seedOnBoot) return;
  const specsDir = path.join(config.seedDir, 'specs');
  const consumersDir = path.join(config.seedDir, 'consumers');
  if (!fs.existsSync(specsDir)) {
    console.log(`[seed] no specs dir at ${specsDir} - skipping seed`);
    return;
  }
  const { rows } = await query('SELECT COUNT(*)::int AS n FROM services');
  if (rows[0].n > 0) {
    console.log('[seed] services already registered - skipping seed');
    return;
  }

  console.log('[seed] importing starter kit...');
  const serviceDirs = fs
    .readdirSync(specsDir, { withFileTypes: true })
    .filter((d) => d.isDirectory())
    .map((d) => d.name)
    .sort();

  const registered = [];
  for (const dir of serviceDirs) {
    const files = fs
      .readdirSync(path.join(specsDir, dir))
      .filter((f) => f.endsWith('.yaml') || f.endsWith('.yml'))
      .sort();
    if (!files.length) continue;

    const firstText = fs.readFileSync(path.join(specsDir, dir, files[0]), 'utf8');
    const firstDoc = yaml.load(firstText);
    const owner = extractOwner(firstDoc?.info?.description) || 'unknown team';
    const slug = dir;
    try {
      await registerService({
        slug,
        name: firstDoc?.info?.title || slug,
        owner_team: owner,
        owner_contact: null,
        description: firstDoc?.info?.description || null,
      });
      registered.push({ slug, files });
      console.log(`[seed] service ${slug} registered (owner: ${owner})`);
    } catch (err) {
      console.error(`[seed] could not register ${slug}: ${err.message}`);
      continue;
    }

    const service = (await query('SELECT * FROM services WHERE slug = $1', [slug])).rows[0];
    await tryPublish(service, firstText, files[0]);
  }

  // Consumers register before later versions so impact analysis covers them.
  if (fs.existsSync(consumersDir)) {
    for (const file of fs.readdirSync(consumersDir).filter((f) => f.endsWith('.yaml')).sort()) {
      try {
        const doc = yaml.load(fs.readFileSync(path.join(consumersDir, file), 'utf8'));
        const slug = doc.consumer;
        await registerConsumer({ slug, name: slug, team: doc.team || slug, contact: doc.contact || null });
        let n = 0;
        for (const use of doc.uses || []) {
          await registerUsage(slug, {
            provider: use.provider,
            method: use.method,
            path: use.path,
            sends: use.sends || [],
            reads: use.reads || [],
            note: use.note || null,
          });
          n++;
        }
        console.log(`[seed] consumer ${slug} registered with ${n} usage(s)`);
      } catch (err) {
        console.error(`[seed] consumer file ${file} failed: ${err.message}`);
      }
    }
  }

  // Remaining versions, in file order, through the same guarded pipeline.
  for (const { slug, files } of registered) {
    const service = (await query('SELECT * FROM services WHERE slug = $1', [slug])).rows[0];
    if (!service) continue;
    for (const file of files.slice(1)) {
      const text = fs.readFileSync(path.join(config.seedDir, 'specs', slug, file), 'utf8');
      await tryPublish(service, text, file);
    }
  }
  console.log('[seed] done');
}

async function tryPublish(service, text, label) {
  try {
    const result = await publish(service, text);
    const tag =
      result.status === 'PUBLISHED'
        ? `published ${result.from_version || 'new'} -> ${result.to_version}`
        : `BLOCKED ${result.from_version} -> ${result.to_version}`;
    console.log(`[seed] ${service.slug}: ${label} ${tag} (D:${result.counts.DANGEROUS} W:${result.counts.WARNING})`);
  } catch (err) {
    if (err.status === 422) {
      console.log(`[seed] ${service.slug}: ${label} refused at stage ${err.extra?.stage}: ${err.message}`);
    } else {
      console.error(`[seed] ${service.slug}: ${label} unexpected error: ${err.message}`);
    }
  }
}

function extractOwner(description) {
  if (!description) return null;
  const m = /Owner:\s*([^.]+)/i.exec(description);
  return m ? m[1].trim() : null;
}

import { Router } from 'express';
import { query } from './db.js';
import { config } from './config.js';
import { publish, previewPublish, diffVersions, loadServiceBySlug, HttpError } from './services/publish.js';
import {
  listServices,
  getServiceDetail,
  registerService,
  listConsumers,
  registerConsumer,
  registerUsage,
  deleteUsage,
  metrics,
  recentEvents,
} from './services/registry.js';

export const api = Router();

const asyncH = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

/* ---------------------------------- health ---------------------------------- */

api.get(
  '/health',
  asyncH(async (_req, res) => {
    try {
      await query('SELECT 1');
      res.json({ ok: true, service: 'contract-guard', webhook: config.webhookUrl ? 'configured' : 'not configured' });
    } catch {
      res.status(503).json({ ok: false, service: 'contract-guard', error: 'database unavailable' });
    }
  })
);

/* --------------------------------- services --------------------------------- */

api.get(
  '/services',
  asyncH(async (_req, res) => res.json(await listServices()))
);

api.post(
  '/services',
  asyncH(async (req, res) => {
    const created = await registerService(req.body || {});
    res.status(201).json(created);
  })
);

api.get(
  '/services/:slug',
  asyncH(async (req, res) => res.json(await getServiceDetail(req.params.slug)))
);

/* --------------------------- publish / preview / diff ------------------------ */

api.post(
  '/services/:slug/publish',
  asyncH(async (req, res) => {
    const service = await loadServiceBySlug(req.params.slug);
    if (!service) throw new HttpError(404, `Service "${req.params.slug}" not found. Register it first.`);
    const yamlText = extractSpecText(req);
    if (!yamlText) throw new HttpError(400, 'Send the OpenAPI YAML as the request body (text/yaml) or as JSON { "yaml": "..." }.');
    const result = await publish(service, yamlText);
    res.status(result.status === 'PUBLISHED' ? 201 : 409).json(result);
  })
);

api.post(
  '/services/:slug/preview',
  asyncH(async (req, res) => {
    const service = await loadServiceBySlug(req.params.slug);
    if (!service) throw new HttpError(404, `Service "${req.params.slug}" not found.`);
    const yamlText = extractSpecText(req);
    if (!yamlText) throw new HttpError(400, 'Send the OpenAPI YAML as the request body (text/yaml) or as JSON { "yaml": "..." }.');
    res.json(await previewPublish(service, yamlText));
  })
);

api.get(
  '/services/:slug/diff',
  asyncH(async (req, res) => {
    const service = await loadServiceBySlug(req.params.slug);
    if (!service) throw new HttpError(404, `Service "${req.params.slug}" not found.`);
    const { from, to } = req.query;
    if (!from || !to) throw new HttpError(400, 'Query parameters "from" and "to" (version strings) are required.');
    res.json(await diffVersions(service, String(from), String(to)));
  })
);

/* --------------------------------- versions ---------------------------------- */

api.get(
  '/services/:slug/versions',
  asyncH(async (req, res) => {
    const { rows } = await query(
      `SELECT id, version, revision, counts, created_at, attempt_id
         FROM versions WHERE service_id = (SELECT id FROM services WHERE slug = $1)
        ORDER BY revision`,
      [req.params.slug]
    );
    res.json(rows);
  })
);

api.get(
  '/services/:slug/versions/:version',
  asyncH(async (req, res) => {
    const { rows } = await query(
      `SELECT v.id, v.version, v.revision, v.spec, v.flat, v.changes, v.counts, v.impact, v.created_at, v.attempt_id,
              s.slug AS service_slug
         FROM versions v JOIN services s ON s.id = v.service_id
        WHERE s.slug = $1 AND v.version = $2`,
      [req.params.slug, req.params.version]
    );
    if (!rows.length) throw new HttpError(404, `Version ${req.params.version} of ${req.params.slug} not found.`);
    res.json(rows[0]);
  })
);

api.get(
  '/services/:slug/attempts',
  asyncH(async (req, res) => {
    const { rows } = await query(
      `SELECT id, attempt_no, from_version, to_version, status, counts, changes, impact,
              error_stage, error_message, notified, created_at
         FROM publish_attempts WHERE service_id = (SELECT id FROM services WHERE slug = $1)
        ORDER BY attempt_no DESC`,
      [req.params.slug]
    );
    res.json(rows);
  })
);

/* --------------------------------- consumers --------------------------------- */

api.get(
  '/consumers',
  asyncH(async (_req, res) => res.json(await listConsumers()))
);

api.post(
  '/consumers',
  asyncH(async (req, res) => {
    const created = await registerConsumer(req.body || {});
    res.status(201).json(created);
  })
);

api.post(
  '/consumers/:slug/usages',
  asyncH(async (req, res) => {
    const created = await registerUsage(req.params.slug, req.body || {});
    res.status(201).json(created);
  })
);

api.delete(
  '/usages/:id',
  asyncH(async (req, res) => res.json(await deleteUsage(Number(req.params.id))))
);

/* ----------------------------- impact and metrics ----------------------------- */

api.get(
  '/metrics',
  asyncH(async (_req, res) => res.json(await metrics()))
);

api.get(
  '/events',
  asyncH(async (_req, res) => res.json(await recentEvents()))
);

/* ---------------------------------- errors ----------------------------------- */

api.use((err, _req, res, _next) => {
  if (err instanceof HttpError) {
    return res.status(err.status).json({ error: err.message, ...(err.extra || {}) });
  }
  console.error('[api] unexpected error:', err);
  // Fail safe: report a guard failure instead of leaking a stack or pretending all is well.
  res.status(500).json({ error: 'Contract Guard hit an unexpected error; the operation was not completed.', detail: err.message });
});

/** Accept raw YAML bodies or JSON {yaml: "..."} forms. */
function extractSpecText(req) {
  if (typeof req.body === 'string' && req.body.trim()) return req.body;
  const b = req.body || {};
  if (typeof b.yaml === 'string' && b.yaml.trim()) return b.yaml;
  if (typeof b.spec === 'string' && b.spec.trim()) return b.spec;
  return null;
}

import express from 'express';
import path from 'node:path';
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';
import { config } from './config.js';
import { initSchema, close } from './db.js';
import { api } from './routes.js';
import { seedIfEmpty } from './seed.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const app = express();

app.disable('x-powered-by');
// Specs can be big-ish; 5MB is a generous ceiling for one OpenAPI document.
app.use(express.json({ limit: '5mb' }));
app.use(express.text({ limit: '5mb', type: ['text/yaml', 'application/yaml', 'application/x-yaml', 'text/plain'] }));

app.use('/api', api);

// Static UI (vanilla, no build step).
const uiDir = path.join(__dirname, 'ui');
if (fs.existsSync(uiDir)) {
  app.use(express.static(uiDir));
  app.get(/^\/(?!api\/).*/, (_req, res) => res.sendFile(path.join(uiDir, 'index.html')));
}

// Last-resort error handler (outside /api too).
// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
  console.error('[server] error:', err.message);
  res.status(err.status || 500).json({ error: err.message || 'internal error' });
});

async function main() {
  await initSchema();
  await seedIfEmpty().catch((err) => {
    // Seeding must never stop the registry from serving.
    console.error('[seed] failed:', err.message);
  });
  app.listen(config.port, () => {
    console.log(`contract-guard listening on :${config.port}`);
    if (config.webhookUrl) console.log(`webhook notifications -> ${config.webhookUrl}`);
  });
}

main().catch(async (err) => {
  console.error('fatal startup error:', err);
  await close().catch(() => {});
  process.exit(1);
});

for (const sig of ['SIGINT', 'SIGTERM']) {
  process.on(sig, async () => {
    await close().catch(() => {});
    process.exit(0);
  });
}

