1: /**
2:  * Severity policy. Every structural change gets exactly one flag:
3:  *
4:  *   DANGEROUS   - a correct consumer of the OLD contract can fail against the NEW one.
5:  *                 (Publishes carrying DANGEROUS changes are stopped.)
6:  *   WARNING     - may affect consumers depending on how they use it / not guaranteed to break.
7:  *   DEPRECATED  - nothing breaks yet; a removal is announced (x-sunset date if given).
8:  *   SAFE        - wire-compatible or purely additive for consumers.
9:  *
10:  * Direction matters: relaxing what a server accepts is safe; tightening it is not.
11:  * Adding to a response is safe; removing from a response is not.
12:  */
13: 
14: export const SEVERITIES = ['DANGEROUS', 'WARNING', 'DEPRECATED', 'SAFE'];
15: 
16: export function classify(change) {
17:   const d = change.direction;
18:   switch (change.kind) {
19:     case 'endpoint_added':
20:       return safe('New endpoint; nothing existing depends on it.');
21: 
22:     case 'endpoint_removed':
23:       return dangerous('Endpoint removed. Every caller still using it will fail.');
24: 
25:     case 'endpoint_deprecated':
