37:         `Response status ${change.status} is no longer documented. Clients relying on it lose a documented outcome.`
38:       );
39: 
40:     case 'body_required_changed': {
41:       if (change.to === 'required') {
42:         return dangerous(
43:           change.from === 'absent'
44:             ? 'Request body is now required; callers that sent no body will be rejected.'
45:             : 'Request body became required; callers omitting it will be rejected.'
46:         );
47:       }
48:       return safe('Request body requirement relaxed; every previously valid call stays valid.');
49:     }
50: 
51:     case 'param_added':
52:       if (change.required) {
53:         return dangerous(
54:           `New required ${change.location} parameter "${change.name}"; every caller must start sending it.`
55:         );
56:       }
57:       return safe(`New optional ${change.location} parameter "${change.name}"; callers may ignore it.`);
58: 
59:     case 'param_removed':
