257: function diffNode(a, b, direction, statusPart, common, changes) {
258:   const at = normType(a.type);
259:   const bt = normType(b.type);
260:   let changed = false;
261:   if (at !== bt && !compatibleTypes(at, bt) && a.path !== '') {
262:     changes.push(
263:       mk({
