265:         direction,
266:         path: a.path,
267:         from: at,
268:         to: bt,
269:         locationLabel: statusPart,
270:         ...common,
271:       })
272:     );
273:     changed = true;
274:   }
275:   if (a.required !== b.required && a.path !== '') {
276:     changes.push(
277:       mk({
278:         kind: 'field_requirement_changed',
279:         direction,
280:         path: a.path,
281:         from: a.required ? 'required' : 'optional',
282:         to: b.required ? 'required' : 'optional',
283:         locationLabel: statusPart,
284:         ...common,
285:       })
286:     );
287:     changed = true;
288:   }
289:   const ae = (a.enum || []).map(String);
290:   const be = (b.enum || []).map(String);
291:   if ((ae.length || be.length) && !sameList(ae, be)) {
292:     changes.push(
293:       mk({
294:         kind: 'field_enum_changed',
295:         direction,
296:         path: a.path || '(root)',
297:         added: be.filter((x) => !ae.includes(x)),
298:         removed: ae.filter((x) => !be.includes(x)),
299:         locationLabel: statusPart,
300:         ...common,
301:       })
302:     );
303:     changed = true;
304:   }
305:   const af = a.format || null;
306:   const bf = b.format || null;
