311:         direction,
312:         path: a.path || '(root)',
313:         from: af || '(none)',
314:         to: bf || '(none)',
315:         locationLabel: statusPart,
316:         ...common,
317:       })
318:     );
319:     changed = true;
320:   }
321:   if (b.deprecated && !a.deprecated) {
