323:       mk({
324:         kind: 'field_deprecated',
325:         direction,
326:         path: a.path || '(root)',
327:         sunset: b.sunset,
328:         locationLabel: statusPart,
329:         ...common,
330:       })
331:     );
332:     changed = true;
333:   } else if (b.deprecated && a.deprecated && b.sunset && b.sunset !== a.sunset) {
