351:         direction,
352:         path: a.path,
353:         from: a.additionalPropertiesForbidden ? 'closed' : 'open',
354:         to: b.additionalPropertiesForbidden ? 'closed' : 'open',
355:         locationLabel: statusPart,
356:         ...common,
357:       })
358:     );
359:     changed = true;
360:   }
361:   return changed;
362: }
363: 
364: /* ------------------------------------ helpers ------------------------------------ */
365: 
366: function mk(change) {
367:   if (change.severityOverride) {
368:     change.severity = change.severityOverride;
369:     change.note = change.note || 'Structural change (documented for completeness).';
370:   }
