378: /** Types we never flag: unknown/any on either side, or identical unions of primitives. */
379: function compatibleTypes(a, b) {
380:   const loose = new Set(['any', 'unknown', 'depth-limit', 'cycle']);
381:   if (loose.has(a) || loose.has(b)) return true;
