54:           `New required ${change.location} parameter "${change.name}"; every caller must start sending it.`
55:         );
56:       }
57:       return safe(`New optional ${change.location} parameter "${change.name}"; callers may ignore it.`);
58: 
59:     case 'param_removed':
60:       return safe(
61:         `${change.location} parameter "${change.name}" no longer documented (acceptance relaxed).`
62:       );
63: 
64:     case 'param_renamed':
65:       return safe(
66:         `Path parameter renamed "${change.from}" -> "${change.to}" at the same position; the URL shape and the value sent over the wire are unchanged.`
67:       );
68: 
69:     case 'param_requirement_changed':
70:       if (change.to === 'required') {
71:         return dangerous(`${change.location} parameter "${change.name}" became required.`);
72:       }
73:       return safe(`${change.location} parameter "${change.name}" became optional.`);
74: 
75:     case 'param_type_changed':
76:       return dangerous(
77:         `${change.location} parameter "${change.name}" type changed ${change.from} -> ${change.to}; existing callers may send values the new type rejects.`
78:       );
79: 
80:     case 'field_added': {
81:       if (d === 'request') {
82:         if (change.required) {
83:           return dangerous(
84:             `New required request field "${change.path}"; callers must send it from now on.`
85:           );
86:         }
87:         return safe('New optional request field; sending it stays optional.');
88:       }
89:       return safe('New response field; consumers that ignore unknown fields are unaffected.');
90:     }
91: 
92:     case 'field_removed': {
93:       if (d === 'request') {
94:         if (change.wasRequired) {
95:           return safe('Required request field removed from the contract (acceptance relaxed).');
96:         }
97:         return warning(
98:           'Optional request field removed from the contract; consumers may still send it and strict providers reject unknown fields.'
99:         );
100:       }
101:       return dangerous(
102:         'Response field removed; consumers reading it will break.'
103:       );
104:     }
105: 
106:     case 'field_requirement_changed': {
107:       if (d === 'request') {
108:         if (change.to === 'required') {
109:           return dangerous(
110:             `Request field "${change.path}" became required; callers omitting it will be rejected.`
111:           );
112:         }
113:         return safe(`Request field "${change.path}" became optional (relaxation).`);
114:       }
115:       if (change.to === 'optional') {
116:         return warning(
117:           `Response field "${change.path}" is no longer guaranteed; consumers reading it must handle its absence.`
118:         );
119:       }
120:       return safe(`Response field "${change.path}" is now always present.`);
121:     }
122: 
123:     case 'field_type_changed':
124:       return dangerous(
125:         `"${change.path}" type changed ${change.from} -> ${change.to}; consumers exchanging this value in the old shape will fail.`
126:       );
127: 
128:     case 'field_enum_changed': {
129:       const added = change.added || [];
130:       const removed = change.removed || [];
131:       if (d === 'request') {
132:         if (removed.length) {
133:           return dangerous(
134:             `Values no longer accepted for "${change.path}": ${removed.join(', ')}. Callers sending them will be rejected.`
135:           );
136:         }
137:         return safe(`New values accepted for "${change.path}": ${added.join(', ')}.`);
138:       }
139:       if (added.length) {
140:         return warning(
141:           `New values may appear in "${change.path}": ${added.join(', ')}. Consumers with exhaustive handling must cover them.`
142:         );
143:       }
144:       return warning(
145:         `Values removed from "${change.path}": ${removed.join(', ')}. Consumers depending on seeing them in a flow may misbehave.`
146:       );
147:     }
148: 
149:     case 'field_format_changed':
150:       return warning(`"${change.path}" format changed ${change.from} -> ${change.to}.`);
151: 
152:     case 'field_strictness_changed':
153:       if (d === 'request') {
154:         return dangerous(
155:           `Unknown extra fields are no longer accepted on "${change.path}"; callers sending additional fields will be rejected.`
156:         );
157:       }
158:       return warning(`Unknown extra fields are no longer documented on "${change.path}".`);
159: 
160:     case 'field_deprecated': {
161:       const base = `"${change.path}" is now deprecated`;
162:       if (change.sunset) {
163:         const past = isPast(change.sunset);
164:         return deprecate(
165:           `${base}${past ? '; its sunset date has already passed' : `; removal planned for ${change.sunset}`}${change.who ? ` (used by: ${change.who})` : ''}.`
166:         );
167:       }
168:       return deprecate(`${base}; no removal date given.`);
169:     }
170: 
171:     default:
172:       return safe('Recognised but unclassified structural change.');
173:   }
174: }
175: 
176: function dangerous(note) {
177:   return { severity: 'DANGEROUS', note };
178: }
179: function warning(note) {
180:   return { severity: 'WARNING', note };
181: }
182: function deprecate(note) {
183:   return { severity: 'DEPRECATED', note };
184: }
185: function safe(note) {
186:   return { severity: 'SAFE', note };
187: }
188: 
189: function isPast(dateStr) {
190:   const t = Date.parse(dateStr);
191:   return Number.isFinite(t) && t < Date.now();
192: }
193: 
194: /** Aggregate a change list into verdict counts + one-line summary. */
195: export function summarise(changes) {
196:   const counts = { DANGEROUS: 0, WARNING: 0, DEPRECATED: 0, SAFE: 0 };
197:   for (const c of changes) counts[c.severity] = (counts[c.severity] || 0) + 1;
198:   return counts;
199: }

