test('diff stage: two identical wire models produce zero changes', () => {
  const flat = analyse(dump(doc({ '/things': getOp({ '200': resp(obj({ x: s('string') }, ['x'])) })) }), null, []).flat;
  assert.deepEqual(diffSpecs(flat, flat), []);
});

test('diff stage: path params pair by position - a two-slot name swap is two renames, not add/remove', () => {
  const oldFlat = analyse(
    dump(doc({ '/i/{a}/{b}': getOp({ '200': resp(obj({ x: s('string') })) }, [{ name: 'a', in: 'path', required: true, schema: s('string') }, { name: 'b', in: 'path', required: true, schema: s('string') }])) }),
    null, []
  ).flat;
  const newFlat = analyse(
    dump(doc({ '/i/{b}/{a}': getOp({ '200': resp(obj({ x: s('string') })) }, [{ name: 'b', in: 'path', required: true, schema: s('string') }, { name: 'a', in: 'path', required: true, schema: s('string') }])) }),
