test('impact stage: request changes match against sends, response changes against reads', () => {
  // response side: only the reader of x is affected by its removal
  const responseSide = analyse(
    dump(doc({ '/t': getOp({ '200': resp(obj({}, [])) }) })),
    analyse(dump(doc({ '/t': getOp({ '200': resp(obj({ x: s('string') }, ['x'])) })) }), null, []).flat,
    [usage('reader', 'GET', '/t', [], ['x']), usage('sender-only', 'GET', '/t', ['x'], [])]
  );
  const removal = responseSide.changes.find((c) => c.kind === 'field_removed');
  assert.equal(removal.severity, 'DANGEROUS');
  assert.deepEqual(removal.affected.map((a) => a.consumer), ['reader']);
  assert.ok(removal.affected[0].via.some((v) => v.includes('reads x')));

  // request side: only the sender of y is affected by y becoming required
  const requestSide = analyse(
    dump(doc({ '/t': { post: { requestBody: { required: true, content: { 'application/json': { schema: obj({ y: s('string') }, ['y']) } } }, responses: { '201': resp(obj({ x: s('string') })) } } } })),
    analyse(dump(doc({ '/t': { post: { requestBody: { required: true, content: { 'application/json': { schema: obj({ y: s('string') }) } } }, responses: { '201': resp(obj({ x: s('string') })) } } } })), null, []).flat,
    [usage('sender', 'POST', '/t', ['y'], []), usage('reader-only', 'POST', '/t', [], ['x'])]
  );
  const requirement = requestSide.changes.find((c) => c.kind === 'field_requirement_changed');
  assert.equal(requirement.severity, 'DANGEROUS');
  assert.deepEqual(requirement.affected.map((a) => a.consumer), ['sender']);
  assert.ok(requirement.affected[0].via.some((v) => v.includes('sends y')));
});

test('impact stage: a new required field affects callers that do not send it or a parent of it', () => {
  const base = analyse(
    dump(doc({ '/t': { post: { requestBody: { required: true, content: { 'application/json': { schema: obj({ rider: obj({ age: s('integer') }, ['age']) }, ['rider']) } } }, responses: { '201': resp(obj({ x: s('string') })) } } } })),
    null, []
  ).flat;
  const r = analyse(
    dump(doc({ '/t': { post: { requestBody: { required: true, content: { 'application/json': { schema: obj({ rider: obj({ age: s('integer'), ncb: s('integer') }, ['age', 'ncb']) }, ['rider']) } } }, responses: { '201': resp(obj({ x: s('string') })) } } } })),
    base,
    [usage('sends-parent', 'POST', '/t', ['rider'], []), usage('sends-sibling', 'POST', '/t', ['rider.age'], []), usage('sends-target', 'POST', '/t', ['rider.ncb'], [])]
  );
  const added = r.changes.find((c) => c.kind === 'field_added' && c.path === 'rider.ncb');
  assert.equal(added.severity, 'DANGEROUS');
  const affectedConsumers = added.affected.map((a) => a.consumer);
  assert.ok(!affectedConsumers.includes('sends-parent'), 'sending the parent object covers the new child');
  assert.ok(affectedConsumers.includes('sends-sibling'), 'a sibling field does not cover the new child');
  assert.ok(!affectedConsumers.includes('sends-target'), 'already sending the field is covered');
  const sibling = added.affected.find((a) => a.consumer === 'sends-sibling');
  assert.ok(sibling.via.some((v) => v.includes('does not send rider.ncb')));
});

test('impact stage: subtree interest - reading "premium" is affected by a change on "premium.total"; unrelated readers are not', () => {
