4:  * Match registered consumer usages against the change list.
5:  *
6:  * A usage = { consumer, team, method, path, sends: [], reads: [] } declared by a
7:  * consuming service. Impact is computed per change and rolled up per consumer, so the
8:  * UI can answer "who would this version affect?" without re-deriving anything.
9:  *
10:  * Matching rules (conservative / fail-safe):
11:  *  - usages attach to an endpoint when method matches (or usage says ANY) and the
12:  *    normalised route shape matches, so `/quotes/{id}` and `/quotes/{quoteId}` connect;
13:  *  - request-side changes compare against usage `sends`, response-side against `reads`;
14:  *  - a new REQUIRED request field/param affects every usage of the endpoint that does not
15:  *    already declare sending it (its parent object counts as sending it);
16:  *  - removed/changed fields affect usages that read/send the same node or a subtree of it;
17:  *  - removed endpoints/statuses affect every usage of that route.
18:  *
19:  * Usages whose declared route matches no endpoint of the provider are reported back as
20:  * `unmatched` - that is a data-quality signal, not an error.
21:  */
22: export function computeImpact(changes, usages, endpoints) {
23:   // Route shapes (methodless) detect "usage points at no endpoint at all";
24:   // full endpoint keys (METHOD + shape) attach a usage to a specific change.
25:   const routeShapes = new Set(endpoints.map((e) => e.routeShape || normalizeShape(e.path)));
26:   const consumerFindings = new Map(); // consumer -> { team, findings: Set, usages: Set }
27: 
28:   for (const usage of usages) {
29:     if (!consumerFindings.has(usage.consumer)) {
30:       consumerFindings.set(usage.consumer, { team: usage.team, findings: new Set(), usages: new Set() });
31:     }
32:     const entry = consumerFindings.get(usage.consumer);
33:     entry.usages.add(`${usage.method} ${usage.path}`);
34:   }
35: 
36:   for (const change of changes) {
37:     if (change.kind === 'endpoint_added') {
38:       change.affected = [];
39:       continue;
40:     }
41: 
42:     // A SAFE change is wire-compatible by definition: nobody is affected by it.
43:     // We still note matched usages' via details for severities that matter.
44:     const changeShape = shapeOf(change);
45:     const targetUsages = usages.filter(
46:       (u) =>
47:         (u.method === change.method || u.method === 'ANY' || u.method === '*') &&
48:         u.routeKey === changeShape
49:     );
50: 
51:     // endpoint_removed / status_removed / body tightening affect the whole usage;
52:     // field-level changes need the send/read intersection.
53:     const fieldLevel = isFieldLevel(change);
54:     const affectedUsages = fieldLevel ? matchFieldChange(change, targetUsages) : targetUsages.map((usage) => ({ usage, via: [] }));
55: 
56:     const affected = change.severity === 'SAFE'
57:       ? []
58:       : affectedUsages.map(({ usage, via }) => {
59:           const entry = consumerFindings.get(usage.consumer);
60:           entry.findings.add(change.id || `${change.kind}@${change.path || change.name || change.endpoint}`);
61:           return {
62:             consumer: usage.consumer,
63:             team: usage.team,
64:             usage: `${usage.method} ${usage.path}`,
65:             via,
66:           };
67:         });
68:     change.affected = affected;
69:   }
70: 
71:   // Unmatched usages: declared routes that no endpoint of the provider satisfies.
72:   const unmatched = [];
73:   for (const usage of usages) {
74:     if (!routeShapes.has(usage.routeKey)) {
