96: function shapeOf(change) {
97:   const key = change.endpointKey || '';
98:   const i = key.indexOf(' ');
99:   return i === -1 ? key : key.slice(i + 1);
100: }
101: 
102: function normalizeShape(path) {
103:   return String(path).replace(/\{[^/}]*\}/g, '{}');
104: }
105: 
106: function isFieldLevel(change) {
107:   switch (change.kind) {
108:     case 'endpoint_removed':
109:     case 'endpoint_deprecated':
110:     case 'status_removed':
111:     case 'body_required_changed':
112:     case 'param_added':
113:     case 'param_requirement_changed':
114:       return false;
115:     default:
