122:  * for usages whose declared paths intersect the change.
123:  */
124: function matchFieldChange(change, targetUsages) {
125:   const reqSide = change.direction === 'request';
126:   const changedPath = change.param ? change.name : change.path;
127:   const affected = [];
128: 
129:   // A root array response documents item fields as `[].field`; consumers just say `field`.
