137:   for (const usage of targetUsages) {
138:     const declared = reqSide ? usage.sends : usage.reads;
139:     // path parameters are sent by the caller too
140:     const pool = reqSide ? [...declared, ...usage.pathParamNames] : declared;
141:     const via = [];
