145:         via.push('request now requires this');
146:       } else if (!pool.some((s) => pathVariants.some((v) => sameOrAncestor(v, s)))) {
147:         via.push(`does not send ${changedPath}`);
148:       } else {
149:         continue; // already sending it (or a child of it) - not affected
150:       }
151:     } else if (!changedPath || changedPath === '(root)' || changedPath.startsWith('(body schema')) {
152:       // e.g. enum change on the body root or schemaless areas - assume everyone touching the endpoint
153:       via.push('uses this endpoint');
154:     } else {
155:       const hits = [];
156:       for (const s of pool) {
